export default [{"id":336,"question":"ما حكم الإبرة في العضل أو الوريد في رمضان، وهي للعلاج وتسكين الألم؟","title":"حكم الإبرة في العضل أو الوريد للصائم","answer":"الجواب: الصحيح أنه لا حرج فيها، لكن إذا أجَّلها إلى الليل يكون أحوط، وإلا فلا تُبطل الصوم، وإبر العضل أقلّ وأسهل، ما دامت لإسكان الألم فلا بأس، أو لتخدير العضو حتى يُعالج؛ لا بأس، أما إبر التَّغذية فإنها تُفطّر.","link":"https://binbaz.org.sa/fatwas/4424/حكم-الابرة-في-العضل-او-الوريد-للصاىم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0389.mp3","categories":["مفسدات الصيام","ما لا يفسد الصيام"]},{"id":337,"question":"ما حكم سحب الدم للتَّحليل؟","title":"حكم سحب الدم من الصائم للتحليل","answer":"الجواب: كذلك لا حرج فيه، سحب الدم للتَّحليل الصحيح أنه لا حرج فيه؛ لأنه شيء قليل لا يُشبه الحجامة.\nس: ولو كثر؟\nالشيخ: الغالب أنه يكون قليلًا، أما إذا كان للتَّبرع لإسعاف المرضى فهذا ينبغي له القضاء إذا دعت الحاجة، وإن تيسر تأجيله إلى الليل فهو أوْلى، إذا كَثُر فالقضاء أحوط.","link":"https://binbaz.org.sa/fatwas/4425/حكم-سحب-الدم-من-الصاىم-للتحليل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0390.mp3","categories":["مفسدات الصيام","ما لا يفسد الصيام"]},{"id":425,"question":"ما حكم استعمال حبوب تأخير العادة الشهرية في شهر رمضان؟","title":"حكم استعمال الحبوب لتأخير العادة الشهرية في رمضان","answer":"الجواب: لا حرج، إذا تعاطت بعض الحبوب؛ حتى لا تأتيها العادةُ في رمضان حتى تُصلي مع الناس وتصوم مع الناس؛ لا بأس. وهكذا في أيام الحج؛ حتى تطوف مع الناس وحتى تؤدي مناسك الحج مع الناس؛ لا حرج في ذلك؛ لأنها لا يضرُّها ذلك إن شاء الله، إذا كانت ممن لا تضرّها الحبوب. وإذا كانت ذات زوجٍ فالأحوط مشاورة الزوج في ذلك حتى لا يلحقها حرج.","link":"https://binbaz.org.sa/fatwas/4849/حكم-استعمال-الحبوب-لتاخير-العادة-الشهرية-في-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0483.mp3","categories":["قضايا المرأة","ما لا يفسد الصيام","النظر والخلوة والاختلاط"]},{"id":1618,"question":"النُّخامة إذا كانت في الحلق وتعمّدتُ جمعها في الحلق ومن ثَمَّ ابتلعتُها وأنا صائم، فما الحكم؟","title":"ما حكم ابتلاع الدم والنخامة ونحوها للصائم؟","answer":"الجواب:\nكأنَّك عندك وساوس، في الحلق ما تضرّ، وإذا وصلت للفم ما يجوز بلعها، تَلْفظْها، أمَّا إذا راحت من الحلق ما يضرّ.\nس: إذا جمعتُها في الفم تعمُّدًا؟\nج: إذا راحت من الحلق ما يضرّ، جمعتَها أو ما جمعتَها، ما دامت في الحلق ما بعد صارت خارجًا.\nس: استنشقتُ الماء في يوم وأنا صائم ومن ثَمَّ دخل إلى الحلق؟\nج: إذا كنتَ ما تعمّدت ما عليك شيء، لكن السنة عدم المبالغة للصائم، لا يُبالغ في الاستنشاق.\nس: طلع من المعدة إلى الحلق ثم تعمّدتُ بلعه مرةً أخرى؟\nج: ما دام ما خرج ما يضرّ.\nس: حكم الدم إذا نزل في الفم ثم تعمّدتُ ابتلاعه؟\nج: إذا تعمّدت تُفطر إذا وصل للفم.\nس: في حكم الاستنشاق سألتُ شيخنا وقال: إنَّك تُفطر؟\nج: لا، إذا تعمّدتَ ابتلاع الدم تُفطر.\nس: في حكم استنشاق الماء؟\nج: إذا كان على طريق الاستنشاق ولكن غلبك الماء.\nس: سألتُ شيخنا وقلتُ له: استنشقتُ ولم أتعمد ودخل إلى الحلق.\nج: ما يضرّ.\nس: قال: يفطر؟\nج: لا، ما يفطر، ما عنده خبر، إذا ما تعمّدتَ فلا شيء عليك.\nس: ما نأخذ بقوله يعني؟\nج: ما عليك شيء.","link":"https://binbaz.org.sa/fatwas/21722/ما-حكم-ابتلاع-الدم-والنخامة-ونحوها-للصاىم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسائل في الصيام.mp3","categories":["مفسدات الصيام","ما لا يفسد الصيام"]},{"id":2516,"question":"استعمال المعجون في رمضان هل يضر؟","title":"ما حكم معجون الأسنان في رمضان؟","answer":"الجواب:\nلا، ما يضر، لا يبلع بس، يغسل به ويتفله، ما يضر مثل ما يتمضمض بالماء.","link":"https://binbaz.org.sa/fatwas/22646/ما-حكم-معجون-الاسنان-في-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يضر استعمال المعجون في رمضان.mp3","categories":["ما لا يفسد الصيام"]},{"id":2674,"question":"التطعيم يُفَطِّر إن كان في الوَرْك أو في الكتف؟","title":"هل يُفَطِّر التطعيم في الوَرْك أو الكتف؟","answer":"الجواب: إذا كان في العَضَل أسهل، في العضل أسهل، ولكن جعله في الليل يكون أحوط خروجًا من خلاف العلماء، أو قبل دخول الشهر، يُطعّمون قبل دخول الشهر.\nس: وإذا ما تمكن إلا في رمضان...؟\nالشيخ: يكون في الليل أحوط أبْعَد عن الخلاف، وإذا كان في العضل فهو أسهل.\nس: إذا كانت في العضل يُطَعِّمونهم؟\nالشيخ: أسهل، لكن في الليل أحوْط إذا تيسر، وإلا في العَضَل أسهل من العِرْق.","link":"https://binbaz.org.sa/fatwas/22812/هل-يفطر-التطعيم-في-الورك-او-الكتف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يفطر التطعيم إن كان في الورك أو في الكتف.mp3","categories":["ما لا يفسد الصيام"]},{"id":2706,"question":"بالنسبة لدهْن العود هل يتطيَّب به الإنسان وهو صائم؟","title":"حكم التَّطَيُّب بدهْن العود للصائم","answer":"الجواب: يتطيَّب به، بس لا يتبخَّر، لا يتسعَّط البخور بأنفه، أما الطِّيب في ثيابه وفي لحيته، دهن عود، دهن ورد، ما في بأس، دهن عنبر، مسك.","link":"https://binbaz.org.sa/fatwas/22848/حكم-التطيب-بدهن-العود-للصاىم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/التطيب بدهن العود للصائم.mp3","categories":["ما لا يفسد الصيام"]},{"id":3934,"question":"هنا يا شيخ الصحيح الصوم يبطل؟","title":"ما أثر المعاصي على الصيام؟","answer":"الجواب: لا، الصحيح نقصها للصوم، المعاصي تنقص الصوم ولا تبطله.","link":"https://binbaz.org.sa/fatwas/24153/ما-اثر-المعاصي-على-الصيام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل المعاصي تبطل الصيام.mp3","categories":["ما لا يفسد الصيام"]},{"id":4159,"question":"الذي يأكل وهو ناسٍ وهو صائم؟","title":"حكم الصائم إذا أكل أو شرب أو جامع ناسيًا","answer":"الجواب: لا شيء عليه، لا كفَّارة، ولا قضاء.\nس: وإذا جامع وهو ناسٍ؟\nج: الصحيح كذلك صومه صحيح، ولا كفَّارة عليه، وبعض العلماء استثنى الجماع، ولا دليلَ على ذلك، ولهذا في اللفظ الآخر: مَن أفطر في رمضان ناسيًا فلا قضاءَ عليه ولا كفَّارة.\nس: إذا رأيتُه يشرب ناسيًا؟\nج: تُنبهه؛ لأنه منكر، إذا رأيتَ مَن يشرب في الصيام أو يأكل نبهه: أنت صائم، تُخبره، تُنكر عليه.","link":"https://binbaz.org.sa/fatwas/24412/حكم-الصاىم-اذا-اكل-او-شرب-او-جامع-ناسيا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الواجب على من أكل أو شرب وهو صائم ناسيًا.mp3","categories":["ما لا يفسد الصيام"]},{"id":4160,"question":"وإذا جامع وهو ناسٍ؟","title":"ما الحكم إذا جامع الصائم ناسيًا؟","answer":"الجواب: الصحيح كذلك صومه صحيح، ولا كفَّارة عليه، وبعض العلماء استثنى الجماع، ولا دليلَ على ذلك، ولهذا في اللفظ الآخر: مَن أفطر في رمضان ناسيًا فلا قضاءَ عليه ولا كفَّارة.","link":"https://binbaz.org.sa/fatwas/24413/ما-الحكم-اذا-جامع-الصاىم-ناسيا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحكم إذا جامع الصائم ناسيًا.mp3","categories":["ما لا يفسد الصيام"]},{"id":5265,"question":"مؤذن أذن قبل الوقت بثلاث دقائق تقريبًا، ما حكم مَن أفطر على أذانه؟","title":"ما حكم من أفطر على أذان قبل الوقت بقليل؟","answer":"الجواب: هذا سهل يُعفى عنه، ما يضر الصوم، لا، ما في شيء.[1]","link":"https://binbaz.org.sa/fatwas/30871/ما-حكم-من-افطر-على-اذان-قبل-الوقت-بقليل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/wazayif ramadan 009.mp3","categories":["ما لا يفسد الصيام"]},{"id":5275,"question":"الذي يأكل الربا في شهر رمضان صومه مقبول؟","title":"ما حكم صيام آكل الربا وبائع الخمر؟","answer":"الجواب: الربا محرم في رمضان وفي غيره، يحرُم أكل الربا في رمضان وفي غيره.\nس: والصيام مقبول؟\nالشيخ: يُرجى له القبول، ولكن على خطر من المعاصي.\nس: في أوروبا في بعض المحلات أصحابها مسلمون وفي رمضان يبيعون الخمر ويبيعون لحم الخنزير؟\nالشيخ: يجب الحذر ويُنكر عليهم، ويُعَلَّمون أن هذا محرم ومنكر حتى يتعلموا ويستفيدوا ويتركوا ذلك.\nس: بس ما يدخل في الصيام؟\nالشيخ: لا، الصيام ينجرح، لكن ما يبطل، ما يبطل الصيام إلا بمفطّراته، لكن كونه يتعاطى المعاصي فالمعاصي تنقص الصيام، تنقص الثواب، تنقص الأجر.[1]","link":"https://binbaz.org.sa/fatwas/30898/ما-حكم-صيام-اكل-الربا-وباىع-الخمر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/waza2ef_ramadan 03.mp3","categories":["ما لا يفسد الصيام"]},{"id":5872,"question":"روي  أن النبي ﷺ رخص بالقبلة لشيخ، ونهى شابًا، فهل هذا الحديث صحيح؟","title":"الحكم على حديث: رخص بالقبلة لشيخ ونهى عنها شاباً","answer":"الجواب: هذا في الصيام، في صيام رمضان كان النبي ﷺ يقبل وهو صائم، ويباشر وهو صائم عليه الصلاة والسلام، فإن الصائم له أن يقبل امرأته، وله أن يباشرها، وهو صائم إذا كان يأمن وقوع الفاحشة، إذا كان شهوته ليست سريعة، ولا يضره ذلك؛ فلا حرج عليه. أما من كانت شهوته سريعة، إذا قبل؛ ينزل المني، أو يخشى أن يجامع أنه يجتنب ذلك، ويروى أنه ﷺ رخص لإنسان في قبلة، ومنعها آخر، فنظر في ذلك، فإذا الذي رخص له شيخ، وإذا الذي نهي عن ذلك شاب، هذا لو صح في سنده ضعف رواه أبو داود وفي سنده ضعف، لكن لو صح فوجهه أن الشيخ في الغالب أضعف شهوة، والشاب أكثر شهوة، وأقوى؛ فلهذا نهي أن يباشر لقوة شهوته. ولكن الحديث صحيح، والأحاديث الصحيحة دالة على جوازه للجميع، الأحاديث الصحيحة دالة على جواز مباشرة المرأة، وتقبيلها في الصوم من الشاب، والشيخ جميعًا، إلا من قويت شهوته، وخاف من شر الفاحشة؛ فإنه يترك ذلك، ولو أنه شيخ، بعض الشيوخ أشد شهوة من الشباب.","link":"https://binbaz.org.sa/fatwas/1216/الحكم-على-حديث-رخص-بالقبلة-لشيخ-ونهى-عنها-شابا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_213.mp3","categories":["ما لا يفسد الصيام"]},{"id":7589,"question":"الرسالة هذه من اليمن وردت من (م. أ. ع)، ووردتنا في نهاية شهر محرم من هذه السنة ألف وأربعماية وواحد، يقول: أما بعد: فإني فتاة من المداومات لسماع البرنامج الموفق نور على الدرب، وأسأل الله له مزيد من النجاح والخير العام، وأرجو أن يثيب الله المشائخ الذين يجيبون على أسئلتنا واستفساراتنا وفقهم الله، وأرجو منكم أن تتفضلوا علي بالرد على الأسئلة الآتية: يقولون: إن هذه الأعمال تجرح الصيام إذا عملناها وقت العصر: أولاً: المضمضة عند الوضوء لصلاة العصر. ثانياً: الاغتسال بالماء أو بالماء والصابون. ثالثاً: دهن الشعر أو أي عضو من أعضاء الوضوء أو شم رائحة العطر، نرجو الإفادة عن ذلك؟","title":"حكم المضمصة والاستنشاق والاغتسال والدهن للصائم","answer":"الجواب: كل هذه لا تفطر الصائم، المضمضة بعد العصر أو في النهار كلها لا تفطر الصائم ولا تضر الصوم، بل شرع الله المضمضة في الوضوء والغسل فلا تضر الصوم، وهكذا الاغتسال في بعد العصر أو في الضحى أو بعد الظهر، كل هذا لا يضر الصائم، وقد اغتسل النبي وهو صائم عليه الصلاة والسلام، وتمضمض وهو صائم، وسأله عمر عن القبلة للصائم؟ فأخبر أنه بمثابة المضمضة؛ لأنه لا تضر الصائم، القبلة وهكذا المضمضة، وهكذا التنظف بالصابون، كله لا يضر الصائم، هكذا دهن الأعضاء، دهن الرأس بالزيت أو بغير الزيت من الأدهان، كل هذا لا يضر الصائم، هكذا شم العطر، شم العطر الذي ليس بسحيق غير مسحوق مثل أنواع الطيب من العود، من الورد لا بأس به، لكن إذا كان سحيقاً، مثل سحيق المسك فإن هذا يطير في الدماغ فيترك، ينبغي تركه في حق الصائم، هكذا البخور لا يتنشقه الصائم؛ لأن بعض أهل العلم يراه يفطر الصائم، فينبغي ترك تنشق العود البخور، وترك تنشق الطيب الذي هو سحيق مثل سحيق المسك؛ لأنه تطير أجزاؤه إلى الدماغ فيفطر عند بعض أهل العلم، فينبغي تجنب ذلك.","link":"https://binbaz.org.sa/fatwas/4642/حكم-المضمصة-والاستنشاق-والاغتسال-والدهن-للصاىم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_019/01907.mp3","categories":["ما لا يفسد الصيام"]},{"id":7643,"question":"أيضاً يقول: هل الجنابة تبطل الصيام أم لا؟","title":"آثار الجنابة على صيام رمضان","answer":"الجواب: الجنابة لها حالات: إن كانت الجنابة وقعت في الليل، بأن جامع أهله في آخر الليل -مثلاً- ثم أصبح قبل أن يغتسل فلا حرج، والصوم صحيح، والنبي ﷺ كان يأتي أهله ثم يصبح جنباً ويغتسل بعد الصباح عليه الصلاة والسلام، أما إن كانت الجنابة في النهار، يعني: جامع أهله في النهار، فهذا آثم وعاص لربه ، والصوم يبطل وعليه كفارة، إذا كان تعمد ذلك عليه كفارة عتق رقبة، فإن عجز صام شهرين متتابعين، فإن عجز أطعم ستين مسكيناً، لكل مسكين نصف صاع من قوت البلد، هذه هي الكفارة في حق من أتى أهله في رمضان في النهار، وصومه يبطل، وعليه القضاء قضاء ذلك اليوم الذي جامع فيه أهله في النهار، أما إذا كان الجماع في الليل ولكنه أصبح جنباً لم يغتسل فلا حرج في ذلك. نعم.","link":"https://binbaz.org.sa/fatwas/4781/اثار-الجنابة-على-صيام-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_035/03504.mp3","categories":["مفسدات الصيام","ما لا يفسد الصيام"]},{"id":7652,"question":"هذه الرسالة عن الحقيقة رمضان والزواج قريباً منه، هذا بشر حسين عطية يقول: تزوجت قبيل رمضان، وألاقي مشكلة كبيرة حيث أن الزواج لا يزال، أو نحن حديثو عهد بالزواج، فأحياناً أنام في الغرفة، وتأتي إلي زوجتي، فأقبلها بعض الأحيان، هل في ذلك شيء أم لا، وأرجو عرض رسالتي هذه على سماحة الشيخ عبد العزيز بن باز وفقكم الله؟","title":"حكم التقبيل للصائم","answer":"الجواب: لا حرج على الزوج أن يقبل زوجته في نهار رمضان أو أن ينام معها، لكن يتجنب وطأها الجماع، لا يجوز له الجماع في نهار الصيام، أما كونه يقبل زوجته أو ينام معها في الفراش أو يضمها إليه كل هذا لا بأس به، كان النبي ﷺ يقبل وهو صائم ويباشر وهو صائم وهو أفضل الناس وهو أتقى الناس لله وأكملهم إيماناً عليه الصلاة والسلام، واستأذنه عمر في ذلك فأذن له في التقبيل.\nفالحاصل إنه لا حرج في ذلك، ويروى أنه استأذنه شيخ يعني شايب في القبلة فأذن له، واستأذنه شاب فلم يأذن له، وفي سنده ضعف.\nقال بعض أهل العلم: إنما كرهه للشاب؛ لأن الشاب أقوى شهوة؛ وبكل حال فالأمر في هذا واسع، والحديث هذا ضعيف، والأحاديث الصحيحة المحفوظة تدل على أنه لا بأس بالتقبيل للزوجة مطلقاً، سواء كان الزوج شيخاً أو شاباً، لكن مع الحذر من الجماع، إذا كانت شهوته شديدة ويخشى إن قبلها أن يقع في الجماع لا يقبل، أما إذا كان لا، يملك نفسه، يمكن أن يستطيع أن يقبل.. يستطيع أن ينام معها.. يستطيع أن يضمها إليه لكن من دون جماع فلا حرج في ذلك كما فعله سيد البشر عليه الصلاة والسلام. نعم.","link":"https://binbaz.org.sa/fatwas/4790/حكم-التقبيل-للصاىم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_036/03603.mp3","categories":["ما لا يفسد الصيام"]},{"id":7653,"question":"طيب لو أنزل بدون جماع في هذه الحالة؟","title":"حكم الصائم إذا أنزل بدون إيلاج","answer":"الجواب: يقضي اليوم ولا شيء عليه، إذا أنزل المني فعليه قضاء اليوم، يصوم هذا اليوم، ويستمر صائم فيه لا يفطر، يستمر صائماً ويمسك، ولكن يقضيه بعد ذلك إذا كان مني، أما إذا كان مذي: الماء اللزج الذي يخرج عند الشهوة، هذا الصحيح أنه لا يضر بالصوم ولا عليه شيء، المذي نفسه، الذي هو ماء لزج يخرج عند حدوث الشهوة، هذا يسمى المذي، هذا لا يضر على الصحيح، أما إذا أنزل المني المعروف فهذا هو الذي يقضى. نعم.\nالمقدم: ولكن كفارة عليه؟\nالشيخ: ولا كفارة إلا بجماع، إذا جامع عليه كفارة.","link":"https://binbaz.org.sa/fatwas/4791/حكم-الصاىم-اذا-انزل-بدون-ايلاج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_036/03604.mp3","categories":["مفسدات الصيام","ما لا يفسد الصيام"]},{"id":7659,"question":"هذه الرسالة وردتنا أو عدة رسائل لكن هذه الرسالة تقوم مقام الرسائل الأخرى، وردتنا من أربع من المستمعات، إحداهن من بيشة (م. ع. ش) والثانية من الرياض فاطمة محمد العتيبية والثالثة نوال سعد بلحارث من عسير والرابعة شريفة عبد الخالق نصر من البحرين تقول الرسالة: إذاعة الرياض برنامج نور على الدرب، نرجو من سماحة الشيخ عبد العزيز بن باز الرئيس العام للبحوث أن يجيبنا على هذين السؤالين تقول: إنني صمت من رمضان الشهر كله، وأنا عندي شك حيث عندي جنين في بطني ومعي نزيف، وأنا الآن صحتي ضعيفة ولا أستطيع الصيام، فإذا كان لم يصح صيامي، فماذا أفعل؟","title":"حكم صيام المرأة الحامل إذا نزل منها دم","answer":"الجواب: إذا صامت المرأة وفي بطنها جنين ومعها نزيف الدم فصومها صحيح؛ لأن هذا النزيف الذي معها وهي حامل لا يؤثر شيئاً، ولا يعتبر حيضاً ولا نفاساً؛ لأن الولد موجود في البطن فليس بنفاس وليس بحيض؛ لأن الغالب أن الحامل لا تحيض، وعلى قول من قال: إن الحامل قد تحيض، يشترطون أن يكون الدم مستقيماً على عادته الأولى، فإذا كانت المرأة التي سألت عن هذا السؤال إنما دمها ملتبس عليها ومتغير.. نزيف يتقطع ويختلف ليس على عادته الأولى القديمة التي تراها قبل الحمل، هذا كله دم فساد، وصومها صحيح، وليس عليها قضاء الصوم والحمد لله؛ لأن الدم الذي مع الحامل في الغالب يكون دم فاسد مختل، يزيد وينقص ويتقدم ويتأخر ويتنوع فهو لا يعتبر، أما لو قدر أنه على حالته الأولى قبل الحمل، على حالته لم يتغير، يأتي على عادته، فهذا قال بعض أهل العلم: إنه حيض وأن عليها أن تجلس ولا تصوم، قاله جماعة من العلماء، وذهب آخرون من أهل العلم إلى أنه ولو كان على عادته وعلى حاله الأولى لا يعتبر، وأن الحامل لا تحيض، هذا قول مشهور عند أهل العلم، لكن الغالب أن الحامل أنه يأتيها دم مضطرب متغير، نزيف لا يستقر له قرار، فهذا لا يعتبر عند الجميع ولا يلتفت إليه بل صومها صحيح وصلاتها صحيحة، وعليها في هذه الحالة أن تتحفظ بقطن ونحوه، وتوضأ لوقت كل صلاة، إذا دخل الوقت تتوضأ لكل صلاة، وتصلي بطهارتها ولو أن الدم لا يزال يخرج معها، لأنها مبتلاة بهذا الشيء مثل صاحب السلس، سلس البول، مثل المستحاضة التي ليست بحامل، سواء بسواء، هذا الدم الجاري معها دم فساد لا يضرها، لكنها تستنجي من بعد دخول الوقت، وتوضأ وضوء الصلاة، وتصلي على حسب حالها، وإذا جمعت بين الظهر والعصر وبين المغرب والعشاء فلا بأس. نعم.\nالمقدم: لكنها لا بد أن تستنجي عند كل صلاة؟\nالشيخ: إيه، إذا دخل الوقت تستنجي وتتوضأ وضوء الصلاة، وتصلي الظهر والعصر جميع، والمغرب والعشاء جميعاً كما علم النبي بعض الصحابيات عليه الصلاة والسلام، وإذا اغتسلت مع ذلك عند صلاة الظهر والعصر غسلاً واحداً والمغرب والعشاء غسلاً واحداً من باب النظافة والنشاط هذا حسن؛ لأنه أوصى به النبي ﷺ بعض النساء المستحاضات. نعم.","link":"https://binbaz.org.sa/fatwas/4825/حكم-صيام-المراة-الحامل-اذا-نزل-منها-دم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_037/03707.mp3","categories":["ما لا يفسد الصيام"]},{"id":7982,"question":"سؤالها الثاني تقول: هل يجوز تذوق ملح الطعام وأنا صائمة وهو لا يروح إلى الحلق بل في طرف اللسان، أرجو التكرم بحل هذين السؤالين ودمتم سالمين؟","title":"حكم تذوق الصائم للطعام أثناء إعداده","answer":"الجواب: لا حرج في ذلك، لا حرج أن المرأة تذوق الطعام أو الرجل الطباخ لا حرج، كونه يذوقه هل هو مالح.. هل هو طيب.. ثم يلفظه لا يبتلع شيء، لكن يذوقه ثم يلقيه لا بأس بذلك لا في حق المرأة ولا في حق الرجل الطباخ، لا حرج في هذا بحمد الله. نعم.","link":"https://binbaz.org.sa/fatwas/5537/حكم-تذوق-الصاىم-للطعام-اثناء-اعداده","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_072/07209.mp3","categories":["ما لا يفسد الصيام"]},{"id":8120,"question":"هذا المستمع أشار إلى اسمه بـ (م) فقط، يقول: حدث حادث علينا في رمضان العصر قرب الفطر، وحدثت في قليل من الجروح، وسال دم مني شيء بسيط، فهل علي قضاء هذا اليوم، رغم أني لم أفطر إلا وقت الإفطار؟","title":"صوم من سال منه الدم أثناء النهار","answer":"الجواب: إذا أصيب الإنسان بجراحات في رجله أو يده بسبب صدام سيارات أو سقوط في حجر أو حفرة أو ما أشبه ذلك، فلا حرج عليه، صومه صحيح ولا يضره ذلك إنما هذا في الحجامة، الحجامة هي التي تفطر الصائم، عند جمع من أهل العلم، وأما ما يصيبه من جراحات لا يضره ذلك، وصومه صحيح.","link":"https://binbaz.org.sa/fatwas/5920/صوم-من-سال-منه-الدم-اثناء-النهار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_087/08707.mp3","categories":["ما لا يفسد الصيام"]},{"id":8152,"question":"عبد الكريم الصالح من الحدود الشمالية بعث بهذه الرسالة عن شهر رمضان يقول: قمت والفجر يؤذن له، فأسرعت للثلاجة وشربت ماء قبل إكمال الأذان، هل صومي هذا صحيح أم لا؟","title":"حكم شرب الصائم للماء أثناء أذان الفجر","answer":"الجواب: لا حرج في ذلك، إذا شرب الإنسان ماء أو لبناً أو \"شاهي\" أو قهوة وهو يؤذن لا حرج في ذلك، لكن إذا تيسر أنه يحتاط ويتقدم؛ حتى لا يقع في الشك فهو أوْْلى، إلا إذا عرف أن المؤذن أذن الصبح وأن الصبح قد طلع وأن المؤذن قد أذن الصبح فإنه لا يشرب، أما مادام لا يدري، على عادة المؤذنين يؤذنوا على الساعات فلا يضره ذلك، إذا شرب وهو يؤذن لا يضره ذلك. نعم.","link":"https://binbaz.org.sa/fatwas/5952/حكم-شرب-الصاىم-للماء-اثناء-اذان-الفجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_090/09004.mp3","categories":["ما لا يفسد الصيام"]},{"id":8213,"question":"سؤال يقول: ما حكم من أفطر سهواً في نهار رمضان وأكمل باقي يومه صائماً، وما حكم من أفطر سهواً في صيام القضاء، ولكنه أكمل باقي يومه صائماً أيضاً؟","title":"حكم صوم من أكل أو شرب ناسياً في رمضان","answer":"الجواب: إذا أكل الصائم أو شرب ناسياً في رمضان أو في قضاء رمضان أو في النذر أو في الكفارات، فصومه صحيح، يكمله ولا شيء عليه؛ لأنه ثبت في الصحيحين عن النبي ﷺ أنه قال: من نسي وهو صائم فأكل أو شرب فليتم صومه، فإنما أطعمه الله وسقاه.\nهكذا جاء في الصحيحين، وهذا من أصح الأحاديث عن رسول الله عليه الصلاة والسلام، وفي اللفظ الآخر خارج الصحيحين عند الحاكم وغيره: من أفطر في رمضان ناسياً فلا قضاء عليه ولا كفارة، هذا هو المعتمد. نعم.","link":"https://binbaz.org.sa/fatwas/6020/حكم-صوم-من-اكل-او-شرب-ناسيا-في-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_095/09506.mp3","categories":["ما لا يفسد الصيام"]},{"id":8332,"question":"الرسالة التالية وصلت إلى البرنامج من العراق، وباعثتها المستمعة فاتن سعيد من بغداد، الأسئلة عراقية المنشأ كما قلت سماحة الشيخ، وصاحبتها تسأل ثمانية أسئلة وتقول: إنني أصوم الشهر المبارك ومتطوعة أيضاً، بمعنى: أني على صحة تسمح لي بالصوم ولا أحس بجوع أو عطش والحمد لله، ولكن ما يضايقني ويجعلني عصبية هو تكون اللعاب بكثرة في فمي ويضعني في وضع حرج، فلا أستطيع التكلم أو الخروج وحتى إذا لم أتكلم فإنه يتكون اللعاب، فماذا أفعل هل أترك الصوم، علماً أني قادرة على الصيام كما أسلفت، وأنا موظفة ولا أستطيع.. -ما أدري لا تستطيع ماذا؟- أرشدوني جزاكم الله خيراً؟","title":"حكم بلع الريق والنخامة في نهار رمضان","answer":"أما صوم رمضان فهذا واجب على جميع المسلمين والمسلمات المكلفين والمكلفات، فالواجب عليك وعلى غيرك من المسلمات المكلفات صوم رمضان وهو أحد أركان الإسلام الخمسة، يقول النبي ﷺ: بني الإسلام على خمس: شهادة أن لا إله إلا الله وأن محمداً رسول الله، وإقام الصلاة، وإيتاء الزكاة، وصوم رمضان، وحج البيت، فعلى المؤمن وعلى المؤمنة صوم هذا الشهر، وأما التطوع فأنت بالخيار، إذا تطوعت بالصيام في غير رمضان فهذا إليك، والصوم فضله عظيم ومن تطوع به فله أجر عظيم، لكن لا يلزمك الصوم إلا في رمضان أو صوم الكفارات أو النذور، وأما ابتداء الصوم تطوعاً فهو غير لازم، إن صمت فلك أجر وإن تركت فلا بأس.","link":"https://binbaz.org.sa/fatwas/6145/حكم-بلع-الريق-والنخامة-في-نهار-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_111/11103.mp3","categories":["ما لا يفسد الصيام"]},{"id":8786,"question":"الرسالة التالية وصلت إلى البرنامج من المستمع الذي رمز إلى اسمه بـ: (س . ع النبهان )، خميس مشيط، يقول في رسالته وفي سؤاله: إنني أود أن أعرف ماذا يجب على من استمنى عمداً في نهار شهر رمضان، وهل ينطبق عليه قول الرسول الكريم ﷺ: من أفطر متعمداً فلن يقبل منه صيام الدهر كله، وإن صامه أفيدونا أفادكم الله؟","title":"ماذا يجب على من استمنى في نهار رمضان؟","answer":"الجواب: أولاً: الاستمناء لا يجوز، لا في رمضان ولا في غيره، الاستمناء محرم ومنكر، عند جمهور أهل العلم لا يجوز فعله، لما فيه من مخالفة قوله تعالى: وَالَّذِينَ هُمْ لِفُرُوجِهِمْ حَافِظُونَ ۝ إِلَّا عَلَى أَزْوَاجِهِمْ أوْ مَا مَلَكَتْ أَيْمَانُهُمْ فَإِنَّهُمْ غَيْرُ مَلُومِينَ ۝ فَمَنِ ابْتَغَى وَرَاءَ ذَلِكَ فَأُوْلَئِكَ هُمُ الْعَادُونَ [المؤمنون:5-7] فالاستمناء غير إتيان الزوجة وغير إتيان ملك اليمين، فهو عبث ومنكر، وهو عدوان.\nثانياً: فيه مضار كثيرة، مع كونه مخالفاً للشرع، فقد قرر الأطباء العارفون بهذه الجريمة، قرروا أن فيها مضار كثيرة على المستمني.\nثالثاً: على من استمنى في رمضان أن يقضي اليوم، عليه أن يتوب إلى الله، وعليه أن يقضي ذلك اليوم؛ لأنه أفطر فيه بهذا الاستمناء، يعني صار في حكم المفطرين وإن لم يأكل ويشرب؛ لكنه صار في حكم المفطرين، فعليه القضاء، قضاء اليوم.\nرابعاً: أما حديث: من أفطر يوم في رمضان لم يكفر عنه صوم الدهر وإن صامه فهو حديث ضعيف عند أهل العلم مضطرب الرواية، ليس بثابت، ولو ثبت لكان معناه عند أهل العلم الزجر والتحذير من الإفطار بغير حق، وليس معناه أنه لا يقضي، لا. بل معناه الزجر عن تعاطي الإفطار بغير حق، والصواب أنه مضطرب ليس بثابت، وعلى من أفطر بالاستمناء أو بغيره أن يتوب إلى الله ويندم، ويبادر بالقضاء، عليه أن يقضي ما عليه مع التوبة والاستقامة، وليس عليه كفارة، فالكفارة تختص بمن جامع في رمضان خاصة، أما الاستمناء في رمضان، أو الأكل عمداً، أو الشرب عمداً في رمضان، فهذا يوجب القضاء ويوجب التوبة والرجوع إلى الله والإنابة إليه، وليس يوجب الكفارة، فافهم يا أخي واحذر. نعم.","link":"https://binbaz.org.sa/fatwas/6947/ماذا-يجب-على-من-استمنى-في-نهار-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_220/22010.mp3","categories":["مفسدات الصيام","ما لا يفسد الصيام"]},{"id":9056,"question":"ماذا أيضاً لو تكرمتم عن المصابين بالربو وهم يتعاطون الأكسجين هل يؤثر هذا الأكسجين على الصيام أو لا؟","title":"حكم استعمال الأكسجين في رمضان للمصابين بالربو","answer":"","link":"https://binbaz.org.sa/fatwas/7212/حكم-استعمال-الاكسجين-في-رمضان-للمصابين-بالربو","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_149/14903.mp3","categories":["ما لا يفسد الصيام"]},{"id":9059,"question":"المصابون بالنزيف؟","title":"حكم صيام المصابين بالنزيف","answer":"الجواب: والنزيف لا يضر أيضاً، مصاب النزيف سواء من فمه أو من أسفل مستمراً معه ليس باختياره فلا يضره مثلما تقدم في أهل الغسيل. نعم.\nالمقدم: كأهل الغسيل تماماً.\nالشيخ: نعم.","link":"https://binbaz.org.sa/fatwas/7217/حكم-صيام-المصابين-بالنزيف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_149/14906.mp3","categories":["ما لا يفسد الصيام"]},{"id":9061,"question":"أفتونا عن صائم يقتل نهاره بالنوم ويحيي ليله بالسهر واللهو أمام عدة وسائل أو أمام عدة ألعاب، كيف تنصحون مثل هؤلاء لو تكرمتم؟","title":"حكم صوم من يقضي نهاره بالنوم وليله بالسهر واللهو","answer":"","link":"https://binbaz.org.sa/fatwas/7219/حكم-صوم-من-يقضي-نهاره-بالنوم-وليله-بالسهر-واللهو","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_149/14907.mp3","categories":["ما لا يفسد الصيام"]},{"id":9216,"question":"أختنا تسأل أيضًا وتقول: هل قطرة العين تؤثر على الصيام؟","title":"حكم استعمال قطرة العين للصائم","answer":"الجواب: هذا فيه خلاف بين أهل العلم، منهم من يرى أنها تؤثر، ومنهم من لا يرى أنها لا تؤثر، والأقرب أنها لا تؤثر؛ لأن العين ليست منفذًا يعني: قويًا، هو منفذ ضعيف، فليس مثل الأكل والشرب ونحو ذلك، فالأحوط جعلها في الليل جعل القطرة في الليل خروجًا من خلاف العلماء، فمن فعلها في النهار فصومه صحيح، لكن إذا وجد طعمها في حلقه فالأحوط له القضاء خروجًا من الخلاف.\nالمقدم: نعم، وهذا ما يحصل فعلًا سماحة الشيخ.\nالشيخ: نعم، يحصل كثيرًا.\nالمقدم: يحصل أن الإنسان يطعمها في نحره إذا قطر في عينه.\nالشيخ: هذا يحصل بعض الأحيان. نعم. إذا ما حصل فالأحوط القضاء وإن لم يحصل فلا شيء، وهكذا الكحل. نعم.","link":"https://binbaz.org.sa/fatwas/7375/حكم-استعمال-قطرة-العين-للصاىم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_182/18206.mp3","categories":["ما لا يفسد الصيام"]},{"id":9270,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من الرياض وباعثها أحد الإخوة يقول: أخوكم في الله (م. ع. ح) أخونا يقول: كنت من قبل أربع سنوات من الآن من الشباب الطيبين وملتزم بالصلاة والسنة، ولكنني صاحبت جلساء سوء وبدأت أترك هذا الطريق حتى أصبحت أتهاون في أداء الصلاة، وارتكبت إحدى المعاصي في نهار رمضان منذ حوالي ثلاث سنوات، وبدأت من العام الماضي أشعر بذنبي ورجعت إلى ما كنت عليه باتباع السنة وإقامة الصلاة، ولكن كل ما تذكرت الذي عملته في نهار رمضان خاصة عند قيامي لصلاة الفجر حزنت وبدأت عيناي تذرف من الدموع، فأرجو من سماحة الشيخ توضيح ما يجب علي أن أفعله، هل هو صيام أم قضاء وجزاكم الله خير الجزاء.والواقع يذكر بالتفصيل خطيئته التي ارتكبها في نهار رمضان سماحة الشيخ؟","title":"حكم من فعل العادة السرية في نهار رمضان","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فالحمد لله الذي هداك -يا أخي- للرجوع إلى الصواب، ولزوم طريق السنة والجماعة، وصحبة الأخيار، ومن تاب تاب الله عليه، وهذا الذي أصابك من الحزن على ما حصل منك من الانتكاس هذا يدل على خير عظيم، فأبشر بالخير والتوبة يمحو الله بها ما قبلها، من تاب تاب الله عليه، يقول النبي ﷺ: التائب من الذنب كمن لا ذنب له ويقول ﷺ: التوبة تهدم ما كان قبلها فالتوبة تهدم ما جرى منك من تقصير والحمد لله، وهذا الحزن إذا ذكرت سيئتك والبكاء هذا خير عظيم وفائدة كبيرة، وهذا منك من جنس ما قال بعض السلف: إن العبد ليفعل الذنب فيدخل به الجنة، ويفعل الحسنة فيدخل بها النار، قيل: كيف ذلك؟ قال: يفعل الحسنة فيعجب بها ويتكبر بها ويتعاظم بها فيدخل بها النار، ويفعل السيئة ثم يندم كلما ذكرها ويحزن كلما ذكرها فيدخل بها الجنة.\nفأنت بهذه التوبة وبهذا الندم وبهذا الحزن يرجى لك الخير العظيم، ويرجى قبول توبتك، فأنت على خير عظيم.\nأما ما جرى منك في رمضان فعليك عنه الكفارة مع التوبة الصادقة، تصوم اليوم الذي جرى فيه الجماع تقضيه وعليك الكفارة عن الجماع، وهي عتق رقبة إن كنت تستطيع، فإن عجزت صمت شهرين متتابعين، فإن عجزت أطعمت ستين مسكينًا، ثلاثين صاعًا، وأنت أعلم بنفسك، إذا استطعت أن تعتق رقبة توجد في بعض الجهات الإفريقية أرقاء بالتوارث موجودين يباعون وقد اشترينا من ذلك جملة وأعتقناها، وإن عجزت عن ذلك فالصيام شهرين متتابعين فإن لم تستطع أطعمت ستين مسكينًا، كل مسكين يعطى نصف الصاع من التمر أو الأرز أو غيرهما من قوت البلد، ونصف الصاع يقارب كيلو ونصف من الحنطة ونحوها.\nوهذا هو الواجب عليك مع التوبة والاستغفار ومع قضاء اليوم، والمرأة مثله، المرأة كذلك إذا كانت صائمة بالغة المقصود أن عليها مثلك، عليها التوبة والاستغفار وقضاء اليوم وعليها مع ذلك الكفارة إذا كانت مطاوعة، أما إذا كانت مقهورة مغصوبة لا قدرة لها فليس عليها شيء. نعم.\nالمقدم: قد أضطر للتصريح سماحة الشيخ الموضوع ليس موضوع جماع مع طرف آخر، هو ما يسمى بالعادة السرية عند الشباب؟\nالجواب: ما هو جماع؟ العادة السرية لا، العادة السرية ما فيها إلا قضاء ما فيها كفارة، العادة السرية فيها القضاء فقط، قضاء اليوم والتوبة والاستغفار والحمد لله.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7433/حكم-من-فعل-العادة-السرية-في-نهار-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_183/18301.mp3","categories":["مفسدات الصيام","ما لا يفسد الصيام"]},{"id":9312,"question":"هل يجوز استعمال الإبر المقوية للصائم في رمضان؟","title":"حكم استعمال الإبر المقوية في رمضان","answer":"الجواب: لا حرج في ذلك على الصحيح لا حرج في ذلك، الإبر المقوية والمسكنة للآلام كل هذا لا بأس به، الممنوع الإبر المغذية، الحقن التي تغذي هذه تفطر الصائم، لكن إذا اضطر إليها واحتاج إليها يعطى إياها ويفطر حكمه حكم المرضى، أما إبر للتقوية أو تسكين الألم أو أخذ عينة من الدم أو ما أشبه ذلك لا تفطر على الصحيح. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7476/حكم-استعمال-الابر-المقوية-في-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_184/18411.mp3","categories":["ما لا يفسد الصيام"]},{"id":9615,"question":"هذه رسالة وردتنا من المرسلة التي رمزت لاسمها بـ (ع. ع) من الرياض، تقول: ما حكم استعمال المرأة حبوباً مانعةً لنزول دم الحيض في شهر رمضان؛ حتى تتمكن من إتمام صومها؟ أفيدونا أفادكم الله؟","title":"حكم استعمال حبوب منع العادة الشهرية في رمضان وغيره","answer":"الجواب: لا حرج في ذلك أن تأخذ الحبوب لمنع الحيض حتى تصلي مع الناس، وتصوم مع الناس، بشرط أن يكون ذلك سليماً لا يضرها، عن مشاورة للطبيب، وعن موافقة من زوجها، حتى لا تضر نفسها، وحتى لا تعصي زوجها، فإذا كان عن تشاور، وعن احتياط من جهة السلامة من الضرر، فلا بأس. وهكذا في أيام الحج. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7776/حكم-استعمال-حبوب-منع-العادة-الشهرية-في-رمضان-وغيره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_271/27105.mp3","categories":["ما لا يفسد الصيام"]},{"id":9668,"question":"السؤال الرابع في رسالة الأخت إستبرق من العراق تقول فيه: أثناء صيامي لشهر رمضان وضعت قطرة لعيني قبل وقت الإمساك ولم أكن أعلم أنها من المفطرات، وبعد أن علمت هذا من برنامجكم في إحدى الحلقات نسيت ذلك فوضعت القطرة ونزلت إلى البلعوم، شعرت بذلك عندما أحسست بشيء من المرار في فمي، فما هو حكم الشرع في ذلك، أفيدونا أفادكم الله؟","title":"حكم استعمال الكحل وقطر العين للصائم","answer":"الجواب: الصحيح أن القطرة والكحل لا يفطران والمسألة فيها خلاف بين أهل العلم، إذا وصل طعم الكحل أو القطرة إلى الحلق قال بعض أهل العلم: إنه يفطر، والصحيح أنه لا يفطر؛ لأنها ليست منفذًا، العين ليست منفذًا لكن من قضى احتياطًا وخروجًا من الخلاف فلا بأس وإلا فالصحيح أنه لا يفطر، القطرة في الأذن وفي العين والكحل في العين كل هذا الصحيح أنه لا يفطر الصائم؛ لأن العين ليست من منفذًا. نعم.","link":"https://binbaz.org.sa/fatwas/7834/حكم-استعمال-الكحل-وقطر-العين-للصاىم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_194/19416.mp3","categories":["ما لا يفسد الصيام"]},{"id":9829,"question":"يقول: ذهبت إلى دار والدي وأكملت صيامي في ذلك اليوم؛ خوفاً من والدي أن يسألني عن سبب إفطاري، علماً أنه كان عمري في تلك اللحظة حول خمسة عشر سنة والآن عمري يقارب خمسة وأربعين سنة، وأنا الآن أصلي وأصوم وأؤدي جميع فروض الله هو السؤال الذي يمكن أن يؤخذ من عبارته هذه أنه يقول: ذهبت إلى دار والدي وأكملت صيامي، هل من أفطر في الإنزال أو ما شابهه هل يجوز له أن يأكل؟الشيخ: هذا الرجل هو صاحب السؤال الأول؟المقدم: نعم هو صاحب السؤال الأول.","title":"حكم الأكل والشرب لمن أفطر في رمضان بإنزال المني","answer":"الجواب: نعم يلزمه إكمال الصوم ولو أنزل يلزمه إكمال الصوم الذي نزل حصل به حصل له شيء يفطر صيامه ليس له أن يستمر في الإفطار، بل عليه أن يمسك لحرمة الزمن، الزمن محترم زمن صيام، فمن ابتلي بشيء يفطره فإنه لا يجوز له الاستمرار في الفطر، بل يلزمه الإمساك حتى تغيب الشمس ويقضي مع ذلك، فلو أنزل المني بسبب المداعبة والقبلة لزوجته أو في الحرام نعوذ بالله فإنه يقضي هذا اليوم ومع هذا عليه الإمساك وإكمال الصوم، ولا يجوز له أن يقول: أنا ما دام أفطرت بالمني آكل وأشرب لا، عليه أن يكمل صومه ويمسك ومع هذا عليه القضاء، نعم.","link":"https://binbaz.org.sa/fatwas/8003/حكم-الاكل-والشرب-لمن-افطر-في-رمضان-بانزال-المني","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_261/26104.mp3","categories":["مفسدات الصيام","ما لا يفسد الصيام"]},{"id":10052,"question":"أثناء صيامي إذا غسلت فمي أحس بالماء في حلقي، وأحاول إخراجه لكنه يبقى وأحس أنه دخل جوفي، فما حكم صيامي؟","title":"حكم دخول الماء جوف الصائم دون قصد","answer":"الجواب: إذا كان ذلك عن غير قصد فلا يضرك كالناسي، إذا دخل قهراً عليك لا يضرك، لكن ينبغي التوقي عند المضمضة وعند الاستنشاق يتوقى الإنسان ولا يبالغ فلو غلبه شيء إن لم يتعمده لا يضره.","link":"https://binbaz.org.sa/fatwas/8237/حكم-دخول-الماء-جوف-الصاىم-دون-قصد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_303/30318.mp3","categories":["ما لا يفسد الصيام"]},{"id":10059,"question":"أثناء صيامي إذا غسلت فمي أحس بالماء في حلقي، وأحاول إخراجه لكنه يبقى وأحس أنه دخل جوفي، فما حكم صيامي؟","title":"حكم دخول الماء جوف الصائم دون قصد","answer":"الجواب: إذا كان ذلك عن غير قصد فلا يضرك كالناسي، إذا دخل قهراً عليك لا يضرك، لكن ينبغي التوقي عند المضمضة وعند الاستنشاق يتوقى الإنسان ولا يبالغ فلو غلبه شيء إن لم يتعمده لا يضره.","link":"https://binbaz.org.sa/fatwas/8237/حكم-دخول-الماء-جوف-الصاىم-دون-قصد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_303/30318.mp3","categories":["ما لا يفسد الصيام"]},{"id":10125,"question":"المستمع محمد مبارك الدوسري من الرياض- الشفا- المعهد العلمي، بعث يسأل ويقول: ما حكم القطرة، قطرة العين والإنسان صائم هل تؤثر على الصيام؟","title":"حكم القطرة في العين للصائم","answer":"الجواب: الصواب: أنها لا تؤثر والصوم صحيح، لكن ذهب بعض أهل العلم أنه إذا وجد طعمها في الحلق يقضي وهذا من باب الاحتياط، إذا وجد طعمها في الحلق وقضى فهذا من باب الاحتياط، والذي هو الصواب أنها لا تقدح في الصوم لكن إذا جعلها في الليل يكون أحوط، لقوله ﷺ: دع ما يريبك إلى ما لا يريبك، وفي ذلك خروج من خلاف العلماء.\nفجعل القطرة والكحل في الليل في حق الصائم يكون أولى وأحوط، لكن لو فعله في النهار فصومه صحيح. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8302/حكم-القطرة-في-العين-للصاىم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_305/30508.mp3","categories":["ما لا يفسد الصيام"]},{"id":10137,"question":"المستمع محمد مبارك الدوسري من الرياض- الشفا- المعهد العلمي، بعث يسأل ويقول: ما حكم القطرة، قطرة العين والإنسان صائم هل تؤثر على الصيام؟","title":"حكم القطرة في العين للصائم","answer":"الجواب: الصواب: أنها لا تؤثر والصوم صحيح، لكن ذهب بعض أهل العلم أنه إذا وجد طعمها في الحلق يقضي وهذا من باب الاحتياط، إذا وجد طعمها في الحلق وقضى فهذا من باب الاحتياط، والذي هو الصواب أنها لا تقدح في الصوم لكن إذا جعلها في الليل يكون أحوط، لقوله ﷺ: دع ما يريبك إلى ما لا يريبك، وفي ذلك خروج من خلاف العلماء.\nفجعل القطرة والكحل في الليل في حق الصائم يكون أولى وأحوط، لكن لو فعله في النهار فصومه صحيح. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8302/حكم-القطرة-في-العين-للصاىم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_305/30508.mp3","categories":["ما لا يفسد الصيام"]},{"id":10214,"question":"أيضاً تقول: يقول البعض لدينا: إن اللبان لا يفطر، فهل هذا القول صحيح؟","title":"حكم مضغ اللبان للصائم","answer":"الجواب: ليس بصحيح، اللبان إذا كان يعالجه ويبلع ريقه، هذا شبه الطعام؛ لأن له طعم وله ذوق، مثل الذي يمضغ الحلوى يفطر، أما لو جعلها في فمه ثم لفظها ولا بلع شيء ما يضره، لكن ما دام يعلج ويبلع، هو مثل من يعلج الحلوى، أو التمر ويبلع. نعم.\nالمقدم: جزاكم الله خيراً، إذاً بعض الكتب التي أوردت هذا الحكم ......... ؟\nالشيخ: غلط، هذا غلط. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8398/حكم-مضغ-اللبان-للصاىم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_310/31011.mp3","categories":["مفسدات الصيام","ما لا يفسد الصيام"]},{"id":10225,"question":"هل الزيت في الشعر، والكحل، والروائح الكيمائية من المفطرات؟","title":"حكم وضع الزيت للشعر والكحل والحناء للصائم","answer":"الجواب: لا، ما يجعل في الشعر من الزيت أو الدهن أو غير ذلك، أو الحناء ليس بمفطر. نعم، المفطر الشيء الذي يأكله الإنسان بفمه، أو من طريق أنفه، أو من طريق التغذية بالإبر -بالحقن- هذا المفطر، وهكذا ما جاء في الشرع أنه مفطر كالحجامة، والجماع، وخروج المني بالشهوة. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8400/حكم-وضع-الزيت-للشعر-والكحل-والحناء-للصاىم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_310/31012.mp3","categories":["ما لا يفسد الصيام"]},{"id":10391,"question":"من سلطنة عمان المستمع: مبارك بن محمد بن حمود الحبسي فيما يبدو بعث برسالة ضمنها سؤالين في أحد أسئلته يقول: رجل بات جنبًا وقال: سأستيقظ قبل أذان الفجر وذلك في شهر رمضان، ولكنه استيقظ بعد طلوع الشمس، فماذا عليه في صومه وصلاته؟ هل عليه كفارة؟ أم بدل وقضاء ذلك اليوم، ومتى يصلي صلاة الفجر الفائتة؟","title":"حكم من نام في رمضان وهو جنب واستيقظ بعد الشروق","answer":"الجواب: مادام ناويًا الصيام فإن صومه صحيح إذا لم يستيقظ إلا بعد طلوع الشمس ولو ما تسحر صومه صحيح وهو على نية الصوم، وليس من شرط الصوم السحور ولكنه سنة السحور وليس بشرط، وعليه أن يبادر بالصلاة إذا استيقظ، فقد ثبت عنه ﷺ أنه في بعض أسفاره نام عن الصلاة هو وأصحابه فلم يستيقظوا إلا بعدما ضربتهم الشمس، فقام ﷺ وأصحابه وتوضئوا وتحولوا عن مكانهم بعض الشيء وصلى بهم في الحال عليه الصلاة والسلام، كما كان يصلي في وقتها يصلي بهم ويقرأ ويجهر ويؤذن ويقيم ويصلي الراتبة مثلما كانت تصلى في وقتها سواءً بسواء، والصوم صحيح، وليس عليه كفارة؛ لأن هذا ليس باختياره، الله أخذ بنفسه حتى ردها عليه سبحانه وتعالى.","link":"https://binbaz.org.sa/fatwas/8563/حكم-من-نام-في-رمضان-وهو-جنب-واستيقظ-بعد-الشروق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_339/33912.mp3","categories":["ما لا يفسد الصيام"]},{"id":10392,"question":"ماذا يجب على رجل احتلم في نهار رمضان؟ نرجو الإجابة ولكم الأجر والثواب.","title":"حكم من احتلم في نهار رمضان","answer":"الجواب: ليس في الاحتلام شيء، إذا احتلم الرجل في رمضان أو المرأة وهو صائم فلا شيء عليه؛ لأنه ليس باختياره، إذا احتلم أنه يجامع ورأى المني وهكذا المرأة فالصوم صحيح، لا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا [البقرة:286] ليس في طوقه السلامة من ذلك، وهذا محل إجماع بين أهل العلم ليس فيه شيء والحمد لله، وهكذا لو فكر فأنزل صومه صحيح؛ لأنه ليس باختياره. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8564/حكم-من-احتلم-في-نهار-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_339/339013.mp3","categories":["ما لا يفسد الصيام"]},{"id":10652,"question":"له سؤال ثاني: الأخ يقول: بأنه يعمل بمهنة طباخ، يقول: وعندما أكون صائم فلا بد من تذوق الطعام بلساني وبعد ذلك أتمضمض بالماء فهل صيامي صحيح لرمضان الماضي؟ جزاكم الله خيرًا.","title":"حكم تذوق الصائم للطعام","answer":"الجواب: نعم صحيح؛ ذوق الطعام لا يضر، كونه يذوق الطعام هو مالح وإلا طيب لا بأس به، يذوق ويلفظه لا يبلعه لا بأس بذلك، والحمد لله، نعم.","link":"https://binbaz.org.sa/fatwas/8829/حكم-تذوق-الصاىم-للطعام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_285/28514.mp3","categories":["ما لا يفسد الصيام"]},{"id":10689,"question":"الأخت في الله: (ل. ر. ع) من الرياض تسأل أيضاً وتقول: ما حكم من تعاطى مفسداً من مفسدات الصوم جاهلاً بالحكم؟ هل عليه إعادة صومه؟","title":"حكم من تعاطى مبطلاً من مبطلات الصوم جاهلاً بالحكم","answer":"الجواب: نعم، عليه أن يعيد الصيام، كمن أكل يظن أنه لا حرج في الأكل في نهار الصيام المفترض أو جامع فإنه يقضي؛ لأنه مفرط بالتساهل وعدم التفقه في الدين، بخلاف الناسي فلا شيء عليه، لو أكل ناسياً أو شرب ناسياً فلا شيء عليه، كما قال عليه الصلاة والسلام: من نسي وهو صائم فأكل أو شرب فليتم صومه، فإنما أطعمه الله وسقاه، وفي اللفظ الآخر: من أفطر في رمضان ناسياً فلا قضاء عليه ولا كفارة، فإذا كان تعاطيه المفطر عن نسيان فإن صومه صحيح، أما إذا أكل أو شرب أو جامع يزعم أنه جاهل بالحكم فإنه يؤمر بالقضاء؛ لأنه في هذه الحالة يعتبر مفرطاً ومتساهلاً، وكان الواجب عليه أن يسأل، ولأن هذه الأمور مما اشتهر بين المسلمين وعرفه المسلمون، فدعوى الجهل فيه بعيد، دعوى الجهل في هذا بعيدة جداً. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8854/حكم-من-تعاطى-مبطلا-من-مبطلات-الصوم-جاهلا-بالحكم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_330/33004.mp3","categories":["مفسدات الصيام","ما لا يفسد الصيام"]},{"id":10764,"question":"من اليمن المستمع علي عباس فاضل بعث برسالة يقول فيها: ما حكم من قبل زوجته في نهار رمضان هل يبطل صومه أو يجرحه؟ وهل عليه كفارة أم لا أفيدونا جزاكم الله خيراً؟","title":"حكم تقبيل الزوجة في نهار رمضان","answer":"الجواب: من قبل زوجته في الصيام فصومه صحيح، وهكذا لو لمسها أو نام معها كل ذلك لا يضر صومه؛ لما ثبت عن عائشة رضي الله عنها قالت: كان النبي ﷺ يقبل وهو صائم ويباشر وهو صائم وسأله عمر عن ذلك قال: إنه قبل امرأته قال: هششت يوماً فقبلت امرأتي، قال: أرأيت لو تمضمضت؟ قال: ...... قال: هكذا، فكما أن المضمضة لا تضر الصوم فهكذا القبلة إذا كان ما خرج منه شيء، أما إذا خرج منه مني يبطل الصوم، أما إذا كان ما خرج شيء قبلها ولمسها ولكن لم يخرج شيء فصومه صحيح، ولو أمذى لم يضره أيضاً على الصحيح، المذي لا يبطل الصوم، وهو الماء اللزج الذي يخرج على أثر الشهوة، على طرف الذكر هذا لا يبطل الصوم، لا يبطل الصوم وإنما يبطل بالمني وهو الماء الغليظ الذي يخرج دفقاً بلذة بسبب الشهوة، وإذا كان يخشى لسرعة شهوته فينبغي له ترك التقبيل، إذا كان يخشى خروج المني لشهوته السريعة فينبغي له ترك ذلك.\nوقد روى أبو داود  ورحمه: أن النبي ﷺ استأذنه إنسان في التقبيل فأذن له، واستأذنه آخر فلم يأذن له، فإذا الذي أذن له شيخ كبير، والذي لم يؤذن له شاب قال بعض أهل العلم: معنى ذلك: أن الشاب قد لا يملك نفسه وقد تسبقه شهوته بخلاف الشيخ الكبير وفي إسناده نظر.\nوالحاصل والخلاصة: أنه إذا كان يخشى فلا يقبل يترك التقبيل، أما إذا كان لا يخشى اللي: يعرف نفسه وأنه لا خطر في التقبيل فلا بأس بذلك ولا حرج. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8945/حكم-تقبيل-الزوجة-في-نهار-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_348/34805.mp3","categories":["ما لا يفسد الصيام"]},{"id":11022,"question":"نعود مع مطلع هذه الحلقة إلى رسالة وصلت إلى البرنامج من المملكة الأردنية الهاشمية، بعثت بها إحدى الأخوات المستمعات من هناك، تقول المرسلة منال عبدالله، أختنا عرضنا لها قضية في حلقة مضت، وفي هذه الحلقة بقي لها بعض القضايا فتسأل في إحداها وتقول: إذا أكل المرء أو شرب وهو صائم صوم نافلة، أو تطوع ناسيًا، فهل يبطل الصيام، أو كيف يكون الأمر؟ جزاكم الله خيرًا.","title":"حكم من أكل أو شرب وهو صائم ناسياً","answer":"الجواب: الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد.  فإن الصائم إذا أكل ناسيًا فإن صومه صحيح، سواءً كان فرضًا أو نفلًا، لقول النبي ﷺ: من نسي وهو صائم فأكل أو شرب فليتم صومه؛ فإنما أطعمه الله وسقاه، متفق على صحته، وهذا من تيسير الله ونعمته  والصائم بشر يعرض له النسيان، فإذا أكل ناسيًا، أو شرب ناسيًا، فإن صومه صحيح، سواء كان فرضًا أو نفلًا، والحمد لله، وعليه أن يتم صومه، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9200/حكم-من-اكل-او-شرب-وهو-صاىم-ناسيا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_367/36701.mp3","categories":["ما لا يفسد الصيام"]},{"id":11162,"question":"رسالة وصلت إلى البرنامج من المستمع عثمان العاقب عبدالله يقول: شربت وأنا صائم، فتذكرت وأمسكت بقية اليوم، هل ما فعلته صحيح؟ أم يجب علي القضاء، جزاكم الله خيرًا؟","title":"حكم من شرب ناسياً وهو صائم","answer":"الجواب:  إذا كنت ناسيًا حين شربت فلا قضاء عليك؛ لقول النبي ﷺ: من نسي وهو صائم فأكل أو شرب فليتم صومه، فإنما أطعمه الله وسقاه. والمقصود أن الصائم إذا شرب ناسيًا أو أكل ناسيًا فصومه صحيح ولا قضاء عليه، والحمد لله. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9338/حكم-من-شرب-ناسيا-وهو-صاىم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_371/37105.mp3","categories":["ما لا يفسد الصيام"]},{"id":11490,"question":"بعد هذا رسالة بعث بها المستمع هاني عبيد الحسين من الجمهورية العربية السورية محافظة حماة، أخونا له قضية يقول فيها: إنني أعاني من مرض في أنفي، ويدعى الجيوب، وإنني لا أستطيع الأكل إذا لم أستعمل دواءً يسمى ..... والقصد من ذلك هو أنني في العام الماضي، وفي شهر الصيام صمت نهارًا، وعندما حل الفطر لم أستطع أكل لقمة واحدة بسبب عدم استخدام الدواء؛ لأنه يفتح المجاري التنفسية، ويسهل للمرء أن يأكل بحرية، ولم أستطع صيام الشهر الماضي بسبب ذلك المرض، وإني أخاف الله العظيم ولا أريد أن أعصيه بشيء، فهل يجوز لي استخدام الدواء قبل حلول الفطر بحوالي نصف ساعة، وهي قطرة في الأنف، واعلموا أني مضطر إلى ذلك، وإذا لم أستخدمه لا أستطيع الصوم، وهذا المرض يجرى له عملية جراحية، ولكن لا توجد لدي تكاليف العملية الجراحية، وإذا انتظرت إلى حلول الفطر ووضعت القطرة؛ فإني سأبقى مدة حوالي نصف ساعة حتى أستطيع الطعام، وأنا أعلم أن تعجيل الفطر واجب، فما هو توجيه سماحة الشيخ؟ هل أستطيع استعمال القطرة الأنفية قبل حلول الفطور بنصف ساعة؛ لأني مضطر؟ جزاكم الله خيرًا.","title":"حكم تعاطي المريض دواء قبل الإفطار في رمضان","answer":"الجواب:  ليس لك ذلك، ولو أخرت، ليس لك ذلك، ولو أخرت الإفطار والحمد لله، فأنت تؤخر حتى تكمل صومك فإذا كملت صومك فالحمد لله؛ لأن الرسول -عليه الصلاة والسلام؛ أخبر أن الأنف منفذ، ولهذا قال: وبالغ في الاستنشاق إلا أن تكون صائمًا فالأنف منفذ للماء والقطرات، فأنت أجل هذا الاستنشاق بالأنف بالقطرة؛ حتى يدخل الوقت، يعني: حتى تغيب الشمس، إلا إذا كان فيه قطرة خفيفة لا تصعد، ولا تنزل .... في الأنف فقط من غير صعود إلى الدماغ، ولا نزولًا إلى الحلق، وهذا لا يمكن أن تكون، يعني: القطرة لابد أن يكون لها نفوذًا. فالحاصل ما دام لها نفوذ في الدماغ، أو نزول؛ فأجلها حتى تغيب الشمس، ولو تأخرت، والحمد لله. المقدم: بارك الله فيكم، يقول: إنه سيتأخر نصف ساعة؟ الشيخ: لا يضر ولو ساعة، والحمد لله. المقدم: إذًا: على أخينا أن يصوم، وإذا ما أذن المغرب؛ فعليه أن يستعمل القطرة، وبعد نصف ساعة يأكل ويشرب. الشيخ: الحمد لله، نعم.  المقدم: بارك الله فيكم، جزاكم الله خير الجزاء.","link":"https://binbaz.org.sa/fatwas/9671/حكم-تعاطي-المريض-دواء-قبل-الافطار-في-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_383/38304.mp3","categories":["مفسدات الصيام","ما لا يفسد الصيام"]},{"id":11874,"question":"تسأل أختنا سؤالًا آخر وتقول: هل التطيب وغسل الوجه بالصابون يفطر الصائم، أم لا؟","title":"حكم استعمال الصائم للطيب","answer":"الجواب:  التطيب لا يفطر الصائم، إذا تطيب بدهن العود، أو الورد في ثيابه، أو بالبخور في ثيابه؛ لا يفطر الصائم، الطيب مطلوب، وهكذا إذا غسل وجهه بالصابون، أو بغير الصابون، لا يضره، لا يضر الصوم، لكن لا يتنشق الطيب.. البخور.. العود... لأن بعض أهل العلم يرى أنه يفطر؛ لأنه له نفوذ في الدماغ، فلا يدخن به في خشمه، يعني: لا يسعطه، إذا جعله تحت ثيابه، أو مر به ... وهو ما قصده؛ فلا يضره، وهكذا الأطياب الأخرى، يتطيب ... دهن العود، دهن الورد.. إلى غير هذا، لا بأس، وهو صائم. نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10058/حكم-استعمال-الصاىم-للطيب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_424/42403.mp3","categories":["ما لا يفسد الصيام"]},{"id":12193,"question":"رسالة وصلت إلى البرنامج من جمهورية مصر العربية، وباعثها مستمع من هناك رمز إلى اسمه بالحروف (ع. ص. أ) يقول في أحد أسئلته: كنت قد خلعت ضرسًا في أول شهر رمضان، وبعد ما خلعته كان يأتي بدم، وأنا صائم، ولا شك أنه كان يدخل في جوفي دم بسيط، ولم أفطر حين ذاك، فما الحكم؟","title":"حكم قلع ضرس الصائم وابتلاع شيء من الدم","answer":"الجواب:  قلع الضرس لا يبطل الصوم، إذا احتاج إلى قلعه لا يبطل الصوم، إذا قلع ضرسه وهو صائم لا يضره، لكن يتوقى دخول الدم إلى جوفه، يلفظه ويتمضمض حتى لا يذهب إلى جوفه شيء، وإذا ذهب شيء من غير عمد، ولا قصد؛ لا يضر الصوم، أما إن تعمد ابتلاع الدم؛ فإنه يبطل صومه، وعليه القضاء، لكن ليس له أن يتعمد ذلك، بل يتوقى ذلك، ويجتهد كما يتمضمض، ويجتهد ألا يذهب شيء إلى جوفه، فلو غلبه شيء من غير قصد؛ لم يضر صومه، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10379/حكم-قلع-ضرس-الصاىم-وابتلاع-شيء-من-الدم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_443/44320.mp3","categories":["ما لا يفسد الصيام"]},{"id":12405,"question":"رسالة وصلت إلى البرنامج من المستمع عبدالله برجس، يقول فيها: أفطرت العام الماضي في رمضان المبارك يومًا واحدًا بعذر شرعي وهو السفر، وقضيت ذلك اليوم، والحمد لله، وكان ذلك اليوم مصادفًا ليوم من أيام الدراسة، حاولت الغش، بل غشيت فقرة من سؤال واحد أثناء الاختبار، علمًا بأن هذا الاختبار اختبار شهري، هل تأثر صيامي بما فعلت؟","title":"حكم صيام من غش أثناء صومه في الاختبار","answer":"الجواب:  الصيام صحيح، لكن ينقص بالمعصية، المعاصي تنقص الصيام، وتنقص العبادات، وتنقص الإيمان، المعاصي كلها تنقص الإيمان، وتضعف الإيمان، ولكن لا يبطل الصوم بها، فلو صام، وحصل منه معصية من غش، أو غيبة، أو كذبة؛ صيامه صحيح، لكن يكون ناقصًا، ليس من جنس صيام من عافاه الله من هذه المعصية، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10610/حكم-صيام-من-غش-اثناء-صومه-في-الاختبار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_455/45510.mp3","categories":["ما لا يفسد الصيام"]},{"id":12493,"question":"بعد هذا ننتقل إلى رسالة بعثت بها إحدى الأخوات تقول: المرسلة فاطمة زايد تسأل وتقول: في شهر رمضان، وفي الأيام الأخرى التي أصومها يحدث لي بعض الوساوس، وهو أنني عندما أتوضأ وآتي إلى المضمضة أشك أحيانًا أن الماء قد دخل فمي، فأجلس أخرج الريق أكثر من ست مرات؛ خوفًا من أن يكون الماء قد دخل، فكم مرة أخرج الماء بعد المضمضة من الوضوء أثناء الصيام؟ جزاكم الله خيرًا، وهل يجوز المسح على الفم دون إدخال الماء فيه أثناء المضمضة؟ وجهوني جزاكم الله خيرُا.","title":"حكم الاكتفاء بمسح الفم بدلاً من المضمضة للصائم","answer":"الجواب:  الواجب على كل مسلم ومسلمة الحذر من الوساوس، فإن الشيطان عدو مبين، فالواجب الحذر منه، ومن وساوسه، يقول الله سبحانه: إِنَّ الشَّيْطَانَ لَكُمْ عَدُوٌّ فَاتَّخِذُوهُ عَدُوًّا إِنَّمَا يَدْعُوا حِزْبَهُ لِيَكُونُوا مِنْ أَصْحَابِ السَّعِيرِ [فاطر:6] الله شرع المضمضة في الوضوء والغسل، فلابد من المضمضة، ولا يجوز الاكتفاء بالمسح على الشفة، بل يجب أن يتمضمض الإنسان، ثم يريق الماء من فمه كما يستنشق أيضًا، ووجود الماء في فمه لا يضر صومه، ولا يخل به، ولكن عليه أن يبصق الماء، لا يبلعه، يبصق الماء إذا كان صائمًا، والحمد لله، أما الوساوس فيجب الحذر منها، والتعوذ بالله من الشيطان، والريق لا يضر الصائم، ريق الصائم لا يضره، فكون المؤمن يتحرج من المضمضة من أجل الصوم هذا غلط كبير جهل، فالمسلم يتمضمض، ويستنشق، ويحذر ما حرم الله عليه من ابتلاع الماء، أو المبالغة في الاستنشاق الذي يوصل الماء إلى جوفه. نعم. المقدم: جزاكم الله خيرًا المسح على الفم لا يجزئ عن المضمضة؟ الشيخ: لا يجزئ، ولا يجوز، بل بدعة. نعم. المقدم: بارك الله فيكم، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10696/حكم-الاكتفاء-بمسح-الفم-بدلا-من-المضمضة-للصاىم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_406/40607.mp3","categories":["ما لا يفسد الصيام"]},{"id":12519,"question":"إحدى الأخوات تقول: المرسلة فاطمة زايد تسأل مجموعة من الأسئلة من بينها سؤال عن السواك، فتقول بالنسبة للسواك: يخرج بعض الدم من اللثة أثناء تنظيف الأسنان، هل هذا يفسد الصوم، أو لا؟","title":"حكم صوم من استخدم السواك فخرج دم من لثته","answer":"الجواب:  لا يضر الصوم، ما يخرج من اللثة عند السواك، أو المضمضة، أو شبه ذلك؛ فلا يضر الصوم، هذا دم يسير يعفى عنه، وهكذا ما يخرج من العين من دم، أو غيره من جراحات لا يضر الصوم، الحمد لله، نعم.  المقدم: جزاكم الله خيرًا، وأحسن إليكم","link":"https://binbaz.org.sa/fatwas/10738/حكم-صوم-من-استخدم-السواك-فخرج-دم-من-لثته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_408/40817.mp3","categories":["ما لا يفسد الصيام"]},{"id":12651,"question":"رسالة وصلت إلى البرنامج من إحدى الأخوات المستمعات تقول: (م. ك. م) من محافظة أراك، تقول في رسالتها: كنت صائمة، وجاء صديق أخي وصافحني، بالرغم أني تهربت منه، والله شاهد على هذا، هل علي إعادة الصوم؟","title":"حكم صيام المرأة التي صافحها أجنبي","answer":"الجواب:  المصافحة للأجنبية لا تجوز، يقول النبي ﷺ: إني لا أصافح النساء وقالت عائشة -رضي الله عنها-: والله ما مست يد رسول الله ﷺ يد امرأة قط -يعني: في البيعة- ما كان يبايعهن إلا بالكلام وهو سيد الخلق، وأكملهم إيمانًا.  فهكذا ينبغي للناس أن يتأدبوا بالآداب الشرعية، وألا يصافحوا النساء إلا إذا كانت محرمًا له، كأخته وعمته ونحو ذلك. أما الصوم فلا يبطل بذلك، ولا يفسد بذلك، الصوم صحيح والمصافحة للأجنبي لا تبطل الصوم، سواء كان أخا الزوج، أو زوج الأخت، أو ما أشبه ذلك، لكن لا يجوز، يجب ترك ذلك والحذر منه، إلا إذا كانت حصل منها مَنيٌ عند المصافحة؛ فهذا تقضي اليوم؛ لأن المصافحة نوع من المباشرة، فإذا باشرت الرجل، وحصل منها مَنيٌ عند المباشرة بالمصافحة، أو بالتقبيل من زوجها مثلًا، حصل مَنيٌ منه، أو منها، فإن الصوم يبطل، وعليها القضاء، تمسك ويمسك الرجل، لا يفطر. لكن يقضي إذا باشر امرأته، أو امرأة أجنبية محرمة عليه -والعياذ بالله- ثم حصل المني؛ فإنه يقضي ذلك اليوم مع التوبة، وهكذا المرأة إذا صافحت إنسانًا، أو قبلت زوجها، أو لامسته، أو كررت النظر في إنسان، فأمنت؛ فإن عليها القضاء، هذا الذي عليه عامة أهل العلم، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10861/حكم-صيام-المراة-التي-صافحها-اجنبي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_458/45803.mp3","categories":["قضايا المرأة","ما لا يفسد الصيام","النظر والخلوة والاختلاط"]},{"id":12716,"question":"يسأل أيضًا ويقول: هل العطور والحناء والكحل وغير ذلك من هذا القبيل مفطر للصائم، أو لا ؟","title":"التفصيل في حكم استعمال العطور للصائم","answer":"الجواب:  هذه الأمور لا تفطر الصائم، الكحل والحناء والتطيب لا يفطر الصائم، لكن لو أخرت المرأة الكحل إلى الليل يكون أفضل وأحوط، وكذلك العطور إذا كان فيها البخور لا يتسعطه الصائم ولا الصائمة، البخور بالعود لا يتسعطه في أنفه، لكن يطيب ثيابه لا بأس، ولا يتسعطه؛ لأنه يفطر عند جمع من أهل العلم إذا تسعطه؛ لأن السعوط له أثر في الدماغ وغيره، فينبغي أن لا يتسعط البخور، ولا أنواع الطيب المسحوقة التي تطير في الدماغ إذا تنشقت. أما الطيب العادي، الدهون العادية، كدهن العود، ودهن الورد، ودهن العنبر، وأشباهها هذه أطياب لا بأس بها، في حق الصائم وغيره. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10929/التفصيل-في-حكم-استعمال-العطور-للصاىم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_460/46004.mp3","categories":["ما لا يفسد الصيام"]},{"id":12719,"question":"ما هو رأيكم فيمن يتناولون الشمة وهم صيام، ويقولون: إنها لا تتسرب إلى الداخل، هل يؤثر ذلكم على صيامهم؟","title":"هل استعمال الشمة والدخان جائز للصائم؟","answer":"الجواب:  الظاهر أنه يجب المنع من ذلك، الشمة والدخان مثل سعوط العود، العود الذي هو طيب يمنع، فكيف بالدخان والشمة من باب أولى. نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10932/هل-استعمال-الشمة-والدخان-جاىز-للصاىم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_460/46007.mp3","categories":["مفسدات الصيام","ما لا يفسد الصيام"]},{"id":12992,"question":"من الجمهورية اليمنية الأخوات (أ. و. ن. د. الأحمدي)، بعثن برسالة يسألن فيها ثلاثة أسئلة.الشيخ: من من؟المقدم: من (أ. و. ن. د. الأحمدي ).الشيخ: من أي بلد؟المقدم: من الجمهورية اليمنية.الشيخ: نعم.المقدم: يسألن ثلاثة أسئلة.السؤال الأول: عن حكم اكتحال المرأة وهي صائمة؟","title":"حكم اكتحال المرأة وهي صائمة","answer":"الجواب:  لا حرج في ذلك، لكن الأفضل أن يكون في الليل، أما الكحل فلا ينقض الصوم، لكن الأفضل أن يكون بالليل، فإن وجدت طعم الكحل في حلقها، فبعض أهل العلم يراها تقضي، فإن قضت احتياطًا؛ فحسن، وإلا فالصواب أن الكحل لا ينقض الصوم، لكن من باب الحيطة ينبغي أن يؤخر في الليل؛ لقوله ﷺ: دع ما يريبك إلى ما لا يريبك نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11209/حكم-اكتحال-المراة-وهي-صاىمة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_470/47015.mp3","categories":["ما لا يفسد الصيام"]},{"id":13822,"question":"السائل معاوية آدم له هذا السؤال عن صيام رمضان يقول: كنت نائم وعندما حان وقت السحور قمت للسحور، وبعد السحور بخمس دقائق أقيمت الصلاة، فهل علي يوم؟ أم علي قضاء؟ مع العلم بأنني لم أسمع الأذان للفجر أفيدوني سماحة الشيخ؟","title":"ما يلزم من تناول السحور بعد أذان الفجر؟","answer":"الجواب: إذا كان الذي أقام الصلاة قد تأخر بعد الأذان المدة التي يجتهد فيها لوضوح الصبح وبيانه فأنت عليك القضاء، يستقضي عند جمهور أهل العلم، أما إذا كان أقام بعد الأذان إنسان يتعجل وأنت انتهيت بعد الأذان حالاً فلا يضرك؛ لأن الأذان على ظن الصبح ليس على رؤية الصبح، فإن الناس يؤذنون على التقويم والحساب فقد يكون أذانهم قبل الصبح بقليل.\nفالحاصل: أنه لا يتيقن طلوع الصبح، فأنت إذا أمسكت عند فراغ الأذان فالصوم صحيح إن شاء الله، لكن إذا تأخرت كثيرًا فإن الغالب أنك أدركت الصبح، فعليك القضاء عند أكثر أهل العلم. نعم.\nالمقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/12190/ما-يلزم-من-تناول-السحور-بعد-اذان-الفجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_530/53004.mp3","categories":["مفسدات الصيام","ما لا يفسد الصيام"]},{"id":13929,"question":"في فقرتها الأخيرة في هذه الحلقة تقول: إنسان شرب في رمضان ظانًا بأن الأذان أذن ولم يؤذن، فماذا عليه في مثل هذه الحالة؟","title":"ما يلزم من شرب في رمضان يظن أنه أُذن للمغرب؟","answer":"الجواب: إذا عرف أنه شرب قبل الغروب يعيد، أما إذا كان يظن الغروب بسبب علامات ظاهرة فلا شيء عليه، أما إذا شرب يظن الغروب ثم بانت الشمس فإنه يقضي ذلك اليوم على الصحيح عند جمهور أهل العلم يقضي هذا اليوم، وهذا هو الأحوط، وبعض أهل العلم لا يراه يقضي؛ لأنه معذور لم يتعمد، ولكن الأقرب والأظهر أنه يقضي، وهكذا لو أكل بعد الفجر يحسب أنه ليل فبان أنه أكل في النهار يقضي، هذا هو الأرجح. نعم.\nالمقدم: شكر الله لكم يا سماحة الشيخ، وبارك الله فيكم وفي علمكم، ونفع بكم المسلمين.","link":"https://binbaz.org.sa/fatwas/12307/ما-يلزم-من-شرب-في-رمضان-يظن-انه-اذن-للمغرب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_538/53822.mp3","categories":["مفسدات الصيام","ما لا يفسد الصيام"]},{"id":14067,"question":"يقول: صادف في رمضان أن أكلنا وشربنا متعمدين بعد أذان الفجر، وقد حصل نقاش طويل بيننا في هذه المسألة نرجو أن توجهونا كيف نتصرف؟ جزاكم الله خيرًا.","title":"ما يلزم من أكل بعد الفجر متعمدًا في رمضان؟","answer":"الجواب: عليكم التوبة والقضاء.. عليكم التوبة والقضاء؛ لأن الأذان يتحرى الوقت؛ والنبي عليه السلام قال: إن بلالًا يؤذن بليل فكلوا واشربوا حتى يؤذن ابن أم مكتوم، وذلك أن ابن أم مكتوم كان يؤذن على الصبح، والأوقاف مجتهدة قد هيئت لهم تقويمًا يسيرون عليه، فإذا أكلتم بعد الأذان فأنتم مخاطرون متلاعبون فعليكم القضاء.\nأما مع الأذان وحين الأذان عند الحاجة فلا بأس، أما بعد الأذان فالواجب القضاء، وعدم التساهل في هذا الأمر، نسأل الله للجميع الهداية.\nالمقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12496/ما-يلزم-من-اكل-بعد-الفجر-متعمدا-في-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_484/48408.mp3","categories":["مفسدات الصيام","ما لا يفسد الصيام"]},{"id":14111,"question":"يسأل أخونا حول نفس الموضوع فيقول: هل يجوز لمن صلى صلاة الفجر في المسجد جماعة، يعني قبل طلوع الشمس بساعة وعشرين دقيقة أن يأكل أو يشرب وذلك في شهر رمضان؛ لأنه لم يتبين الخيط الأبيض من الخيط الأسود، نرجو الإجابة مفصلة مع الأدلة؟ جزاكم الله خيرًا.","title":"هل يجوز الأكل والشرب للصائم بعد أذان الفجر؟","answer":"الجواب: ليس له أن يأكل ولا يشرب بل عليه أن يمسك وأن يصوم؛ لأن الظاهر أن المؤذنين تحروا الأذان وتحروا طلوع الفجر، ثم قد صلى، كيف يصلي ويأكل؟! الصلاة أعظم، إذا كان الفجر ما طلع ما صحت الصلاة، فكيف يصلي ثم يأكل؟! الواجب التحري للصلاة؛ لأنها أعظم من الصوم، فرض الصلاة أعظم من فرض الصوم، فالواجب التحري فإذا غلب على ظنه دخول وقت الفجر صلى الفجر وامتنع من الأكل والشرب، وليس له أن يأكل ويشرب وهو يظن طلوع الفجر ويغلب عليه طلوع الفجر، والله يقول : وَكُلُوا وَاشْرَبُوا حَتَّى يَتَبَيَّنَ لَكُمُ الْخَيْطُ الأَبْيَضُ مِنَ الْخَيْطِ الأَسْوَدِ مِنَ الْفَجْرِ[البقرة:187] والمعنى: حتى تتحققوا طلوع الفجر. فما دام عنده شك له أن يأكل ويشرب، لكن إذا كان في محل لا يظهر فيه طلوع الفجر مثل المدن التي فيها الأنوار فيعمل بالتقاويم المضبوطة والتحري وغلبة الظن، يكفي ذلك ويمتنع من الأكل والشرب. أما إذا كان في الصحراء التي ليس يحول بينه وبين الفجر فيها شيء فإنه يأكل ويشرب حتى يعلم الفجر، حتى يعلم طلوع الفجر كما هو نص القرآن الكريم. أما أن يصلي الفجر ثم يأكل هذا غلط عظيم، ليس له أن يصلي إلا بعد طلوع الفجر، ومتى طلع الفجر باليقين أو بغلبة الظن حرم الأكل والشرب وجازت الصلاة. نسأل الله للجميع الهداية. نعم.\nالمقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12552/هل-يجوز-الاكل-والشرب-للصاىم-بعد-اذان-الفجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_614/61413.mp3","categories":["مفسدات الصيام","ما لا يفسد الصيام"]},{"id":14114,"question":"هل العطر أو العود يفطر الصائم؟","title":"حكم استعمال العطر والعود للصائم","answer":"الجواب: العطر لا يفطر الصائم، إذا تطيب في ثيابه وفي وجهه، لكن البخور ينبغي توقيه لا يتسعطه؛ لأن بعض أهل العلم: رأى أنه يفطر إذا تسعطه، فينبغي له ألا يتسعط البخور؛ لأن له أجزاء تدخل في الدماغ، وتذهب إلى الجوف، فينبغي له ألا يتسعطه، وإن تسعطه ينبغي له القضاء.\nأما جنس الطيب العادي... المائي يجعل في أنفه أو في لحيته أو في غترته ونحو ذلك فهذا لا بأس به، دهن العود دهن الورد لا حرج. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12550/حكم-استعمال-العطر-والعود-للصاىم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_484/48417.mp3","categories":["ما لا يفسد الصيام"]},{"id":14559,"question":"يقول: إذا فسد صيام شخص ما، وهو يغتسل وتسرب الماء إلى حلقه عن طريق فمه أو أنفه، وليس بإرادته فهل عليه إطعام مسكين عن ذلك اليوم؟ وهل عليه الإعادة؟","title":"حكم الصائم إذا دخل الماء إلى حلقه من غير تعمد","answer":"الجواب: ليس عليه إعادة، إذا ما تعمد ليس عليه إعادة، صومه صحيح، وليس عليه إطعام مسكين، لو دخل الماء في حلقه عند الوضوء أو الغسل، أو عند الاستنشاق، ولم يتعمد فصومه صحيح، وليس عليه شيء، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13056/حكم-الصاىم-اذا-دخل-الماء-الى-حلقه-من-غير-تعمد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_489/48909.mp3","categories":["ما لا يفسد الصيام"]},{"id":15129,"question":"سؤاله الآخر يعرض في الحقيقة مشكلة وقعت عليه في رمضان، يقول: يوجد عندي بنت متزوجة، وقد جاءت عندنا هي وزوجها في شهر رمضان، وبعدما صمنا أسبوعًا جاء زملاء زوج بنتي، وذهبوا إلى البر، وخالطهم الشيطان فأكلوا وشربوا، وجاء اليوم الثاني في الصباح -الذي هو زوج بنته- وقال لزوجته: يريد أن تعطيه أكل، فمنعت زوجته، وطلق، إنه يفطر وحلفت يمينًا ما تسوي له أكل، فأصبحت محتارة بين زوج بنتي وبين بنتي؛ لأنه طلق، وهي حلفت يمينًا، فأجبرت زوجة ولدي أن تسوي له أكلًا، فمنعت فغصبتها، وهي ليست راضية، وقامت وعملت له أكلًا، فأكل وشرب ونحن موجودين معه في البيت، ولكننا لم نأكل معه، فماذا يلزمنا هل علينا إثم أو يلزمنا صدقة؟أفيدونا، جزاكم الله عنا ألف خير.","title":"حكم الفطر في رمضان وحكم من أعان على ذلك","answer":"الجواب: لا شك أن الإفطار في رمضان بدون عذر شرعي كبيرة من الكبائر، ومنكر من المنكرات العظيمة إذا كان من غير عذر شرعي.  أما إذا كان بعذر السفر إذا سافروا ما يعد سفرًا، وهو ما يعادل ثمانين كيلو تقريبًا، أو سبعين كيلو تقريبًا، مسافة يوم وليلة تقريبًا، بالمطايا والأقدام، فما يعادل ذلك ويقاربه يسمى سفرًا، ولا حرج في الإفطار فيه. أما ما كان في البيت أو في ضواحي البلد، ولا يسمى سفرًا؛ فهذا الإفطار فيه كبيرة من الكبائر، والذي يعين المفطر على إفطاره شاركه في الإثم؛ لأن الله سبحانه يقول: وَلا تَعَاوَنُوا عَلَى الإِثْمِ وَالْعُدْوَانِ [المائدة:2] فالذي يساعد من أفطر في رمضان بغير عذر بتقديم الطعام أو القهوة أو الشاي أو غير ذلك من الأشربة أو المطعومات؛ آثم مشارك للمفطر في الإثم، لكن صومه صحيح، لا يبطل صومه بالمعاونة، ولكن يكون آثمًا، وعليه التوبة إلى الله. وعليك -أيها الأخ- عند غصبك البنت على صنع الطعام، عليك التوبة إلى الله، فإنك قد أخطأت حين أمرتها بصنع الطعام له، فهي قد أحسنت وأصابت في عدم طاعته؛ لأنه لا طاعة لمخلوق في معصية الخالق، والنبي  قال: إنما الطاعة في المعروف فإذا أمرها زوجها أن تقدم له طعامًا في الصوم صوم رمضان، وهو ليس به عذر، ليس بمريض لا عذر له؛ فهذا حرام ومنكر، ليس له الإفطار، وليس له أمر زوجته بإعداد فطور له، وليس لها أن تعينه على ما حرم الله، ولو غضب، ولو طلق، لا يجوز لها أن تعينه على ما حرم الله عليه وعليها، وطاعة الله مقدمة على طاعة الزوج، وعلى طاعة الأب، وعلى طاعة السلطان، وعلى طاعة الأمير؛ لأن الرسول ﷺ قال: إنما الطاعة في المعروف وقال أيضًا -عليه الصلاة والسلام-: لا طاعة لمخلوق في معصية الخالق نعم، الله المستعان.\nالمقدم: لكن ربما أن الذي قرأناه الآن في رسالة المستمع (ع. ل. هـ) من بلاد غامد يتضح أن الزوج مسافر، وأن زملاءه الذين أتوا إليه مسافرين أيضًا؟\nالشيخ: لا، يقول في البيت........، في البيت.\nالمقدم: إي نعم.\nالشيخ: أمرها في البيت بعدما رجعوا. المقدم: لا هم لا يزالون في سفر في بلاد غامد في سفر؛ لأنه يقول: قدمت لنا بنتي وزوجها زارونا في نهار رمضان، وزاره أيضًا زملاؤه فأصبحوا الجميع مسافرين.\nالشيخ: إذا كانوا مسافرين، وقد عزموا على الإقامة أكثر من أربعة أيام؛ فإنه يلزمهم الصوم هذا الأرجح، وهو قول جمهور أهل العلم: إذا كانوا قد عزموا على الإقامة أكثر من أربعة أيام عند أصحابهم؛ يصوموا معهم، أما في أقل من أربعة أيام، أربعة أيام فأقل فلا يلزمه الصوم إذا كانوا مسافرين، مروا عليهم زوارًا؛ فلا يلزمهم الصوم، وإن صاموا فلا بأس، ولا حرج، أما إذا كانوا قد أرادوا الإقامة عندهم أكثر من أربعة أيام؛ فالذي ينبغي في هذه الحال هو الصوم خروجًا من خلاف العلماء، وعملًا بقول الأكثر؛ ولأن الأصل الصوم، وشك في إجازة الإفطار، نعم.","link":"https://binbaz.org.sa/fatwas/13630/حكم-الفطر-في-رمضان-وحكم-من-اعان-على-ذلك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_657/nour_65702.mp3","categories":["مفسدات الصيام","ما لا يفسد الصيام"]},{"id":15201,"question":"وأول سؤال نطرحه على فضيلته، ورد إلينا من المستمع رمز لاسمه بالأحرف (م. ن. و) من الرياض، يقول: أثناء تأديتي لصلاة الفجر في رمضان يغالبني الريق فأبلعه، وأحس فيه بطعم دم من اللثة، ناتج عن التسوك أو التخلل من الأكل، فهل يؤثر ذلك في صومي أم لا؟","title":"ما حكم بلع الصائم للريق المصحوب برائحة الدم؟","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله رب العالمين، وصلى الله وسلم وبارك على عبده ورسوله، نبينا محمد وعلى آله وأصحابه، ومن سلك سبيله، واهتدى بهداه إلى يوم الدين، أما بعد: فجواب هذا السؤال أن يقال: أما الريق فلا بأس به، كون الإنسان يبلع ريقه هذا شيء لا حرج فيه؛ الريق المعتاد. أما النخامة من الصدر، أو من الرأس، فهذه لا تبلع، متى وصلت إلى فمه، فإن الواجب أنه يقذفها يلفظها، ولا يبتلعها، فإن تعمد ابتلاعها أفطر بذلك على الصحيح، وقضى ذلك اليوم، وأما إذا كان من ريقه شيء آخر من بقايا ما في الأسنان من الأكل من لحم أو خبز أو فاكهة، أو شيء من الدم بسبب السواك، فهذا فيه تفصيل:\nإن علم بذلك فلا يتعمده، بل يلفظه، وإن لم يعلم ذلك بل بلع ريقه كالعادة، ثم أحس بذلك فلا يضره؛ لأنه لم يتعمد ذلك، بمثابة من تمضمض واستنشق فغلبه شيء إلى فمه إلى حلقه من دون قصد، وبمثابة من غلبه السعال أو غلبه القيء من غير قصد، فهذا لا يضره ذلك، إنما الذي يضر التعمد، إذا تعمد ابتلاع شيء وصل إلى فمه من نخامة أو من دم في فمه تعمده، أو طعام في فمه تعمده، هذا هو الذي يضره، أما ما لم يتعمده، بل غلبه فلم يتعمده فهذا لا يضره، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13694/ما-حكم-بلع-الصاىم-للريق-المصحوب-براىحة-الدم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_671/nour_67101.mp3","categories":["ما لا يفسد الصيام"]},{"id":15204,"question":"السؤال الآخر ورد من السائل أبو تركي من الرياض، يقول: أنا رجل أسكن في بيت لوحدي، وذات مرة قمت لأتسحر فنظرت في الساعة، فإذا هي الثالثة صباحًا، بمعنى أن هناك متسعًا من الوقت للسحور، وليس في البيت منفذ لضوء النهار، وفعلاً تسحرت، وحينما أردت الخروج للصلاة -صلاة الفجر- تبين لي أن النهار قد طلع، وأن الناس قد صلوا الفجر، وعادوا إلى منازلهم، فماذا يجب علي في هذه الحالة القضاء أم الكفارة؟ وهل أكمل صيام هذا اليوم أم أفطره؟","title":"حكم من تسحر بعد الفجر ظانًا أنه ما زال الليل","answer":"الجواب: عليك إكمال الصوم في رمضان إذا كان رمضان عليك إكمال الصوم، وعليك القضاء على الصحيح عند أكثر أهل العلم؛ لأنك تساهلت، ولم تعتن بمعرفة أسباب ظهور الصبح، بل تساهلت، ثم تبين لك أنك أكلت في النهار، فعليك القضاء في أصح قولي العلماء، وعند أكثر أهل العلم مع الإمساك في رمضان. أما إذا كان الصوم في غير رمضان، مثل صوم كفارة أو صوم نذر، فهذا لا تمسك تقضي يومًا مكانه، إذا علمت أنك أكلت في النهار تفطر ذلك اليوم، وتقضي يومًا مكانه، والحمد لله.  أما إن كان نافلة فالأمر واسع، النافلة أمرها واسع، لك أن تفطر؛ لأنه نافلة، ولك أن تصوم من جديد، لكن ما دام أكلت في النهار، لا تصم من جديد، بل تفطر؛ لأنه يوم لا يعتد به بسبب الأكل الذي فيه في النهار. فالحاصل: أنه إذا كان صوم رمضان عليك أن تمسك، وتقضي ذلك اليوم، أما إذا كان صوم كفارة، أو صوم نذر، أو صوم نافلة، فإنك تفطره وتقضي يومًا مكانه، بدل الكفارة والنذر، نعم.\nالمقدم: وإذا كان عن قضاء فريضة؟\nالشيخ: ولو كان عن قضاء رمضان كذلك له أن يفطر. المقدم: يعتبر كالنافلة؟ الشيخ: لأن زمانه ما هو محترم، بخلاف زمان رمضان، أما زمن القضاء فإذا أكل في النهار يحسبه ليلًا فإنه يفطر ويقضي بدل ذلك اليوم، ولا يكمل، لا يلزمه الإكمال؛ لأنه لا يفيده شيئًا. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/13695/حكم-من-تسحر-بعد-الفجر-ظانا-انه-ما-زال-الليل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_671/nour_67102.mp3","categories":["مفسدات الصيام","ما لا يفسد الصيام"]},{"id":15448,"question":"السائل من السودان، يقول في هذا  رجل وقع على أهله في ليل رمضان، ثم نام قبل أن يغتسل، ولم يستيقظ لصلاة الفجر، وظل نائمًا حتى الظهر، وهو لا يزال جنبًا، ثم قام واغتسل وصلى الظهر، فماذا عليه؟ وهل صومه ذلك اليوم جائز؟","title":"حكم من أصبح جنبًا في نهار رمضان","answer":"الجواب: نعم، صومه صحيح، إذا كان الجماع في الليل صومه صحيح، ولكنه أخطأ في عدم ضبط الأمور ما جعل ساعة يركدها على الصبح، حتى يقوم، أو قبيل الصبح، أو ينبه أحدًا من أهل بيته يوقظونه، والواجب عليه إذا استيقظ أن يبادر فيصلي الفجر، يغتسل ويصلي الفجر، ثم يصلي بعدها الظهر في وقتها إلى آخره. فالحاصل: أنه مفرط ومتساهل، وصومه صحيح إذا كان نوى الصوم صومه صحيح، ولو نام إلى الظهر، صومه صحيح، لكن عليه التوبة إلى الله من تساهله، وإذا قام يغتسل ويصلي الفجر، سواء قام الضحى أو الظهر يصلي الفجر، ثم يصلي بعدها الصلاة الأخرى، نعم.","link":"https://binbaz.org.sa/fatwas/13963/حكم-من-اصبح-جنبا-في-نهار-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_500/50016.mp3","categories":["ما لا يفسد الصيام"]},{"id":15491,"question":"شخص صام رمضان وهو غير طاهر، أي: على جنابة، هل صيامه مقبول أم ماذا؟","title":"هل يصح صوم من أذن للفجر وهو جنب؟","answer":"الجواب: نعم، الصوم صحيح، ولو ما اغتسل إلا بعد الصبح، كان النبي ﷺ ربما جامع أهله، وأخر الغسل حتى يصبح، فإذا قد جامع في آخر الليل، ثم تسحر وصام، ولم يغتسل إلا بعد الأذان فلا بأس، فلا حرج في ذلك.","link":"https://binbaz.org.sa/fatwas/14018/هل-يصح-صوم-من-اذن-للفجر-وهو-جنب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_569/56907.mp3","categories":["ما لا يفسد الصيام"]},{"id":15551,"question":"تقول السائلة: هل الإنسان إذا تذوق الطعام في رمضان وهو صائم ولم يدخل إلى الحلق، هل يبطل الصيام؟","title":"حكم تذوق الصائم الطعام دون بلعه","answer":"الجواب: لا حرج، يتذوق الطعام، الطباخ والطباخة لهما ذوق الطعام ويلفظانه، لا يبلعانه، يذوقانه ولا بأس، يذوق ولا يبتلع، نعم.","link":"https://binbaz.org.sa/fatwas/14098/حكم-تذوق-الصاىم-الطعام-دون-بلعه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_691/nour_69130.mp3","categories":["ما لا يفسد الصيام"]},{"id":15736,"question":"ما حكم البخور والعطر في أيام رمضان المبارك، بعض الناس يقول: أي البخور والعطر يفطر، والبعض يقولون: بأنه لا يفطر. أفيدونا بالإجابة الصحيحة سماحة الشيخ.","title":"حكم البخور والطيب للصائم","answer":"الجواب: البخور والعطر لا يفطران، له أن يطيب أو يتبخر ولا يفطره ذلك، لكن لا يستنشق البخور أحوط، خروجًا من الخلاف، لا يستنشقه، بل يطيب في ثيابه وبدنه.\nفي الطيب بالورد بدهن العود بالبخور، لكن لا يستنشق البخور، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/14315/حكم-البخور-والطيب-للصاىم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_575/57501.mp3","categories":["ما لا يفسد الصيام"]},{"id":15782,"question":"رسالة وصلت إلى البرنامج من القريات، باعثتها إحدى الأخوات المستمعات من هناك، تقول: إنني أستعمل البخاخ في رمضان وأنا صائمة، وذلك بسبب الربو، وأجد له طعم المرارة فهل يفطر؟","title":"حكم استعمال الصائم لبخاخ ضيق التنفس","answer":"الجواب: إذا كان للضرورة لا لا يفطر -إن شاء الله-، إذا كان للضرورة؛ لأنه ليس شرابًا ولا طعامًا، إنما هو ينفس، هواء ينفس المكظوم، فالصواب أنه لا يفطر، لكن عند الضرورة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14371/حكم-استعمال-الصاىم-لبخاخ-ضيق-التنفس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_742/nour_74208.mp3","categories":["قضايا المرأة","ما لا يفسد الصيام"]},{"id":15802,"question":"رسالة من أحد الإخوة المستمعين، وقع في نهايتها بحرف العين، يقول: بعض من النسوة يستعملن الحبوب في شهر رمضان، زيادة عن الوقت بدون انقطاع؛ لكيلا يأتيهن العذر الشهري، وهذا حتى لا يأكلن يومًا واحدًا من شهر رمضان، هل هذا جائز أم لا؟","title":"حكم استعمال حبوب منع العادة الشهرية لأجل الصوم","answer":"الجواب: لا أعلم في هذا بأسًا، إذا كان لا يضرهن ذلك، لا أعلم في هذا حرجًا؛ لأن لهن مصلحة كبيرة في الصيام مع الناس، وعدم القضاء بعد ذلك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14390/حكم-استعمال-حبوب-منع-العادة-الشهرية-لاجل-الصوم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_743/nour_74306.mp3","categories":["قضايا المرأة","ما لا يفسد الصيام"]},{"id":15872,"question":"تسأل أختنا وتقول: ما حكم غسل وتنظيف الأسنان بالفرشة والمعجون في رمضان؟","title":"حكم استعمال الصائم الفرشة والمعجون","answer":"الجواب: لا حرج في ذلك؛ لكن لا يبلع شيئًا، للرجل والمرأة، يغسل فمه وأسنانه، ويتفل ما يحصل منه، يمجه، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14462/حكم-استعمال-الصاىم-الفرشة-والمعجون","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_744/nour_74412.mp3","categories":["ما لا يفسد الصيام"]},{"id":15875,"question":"تسأل أختنا وتقول: ما حكم غسل وتنظيف الأسنان بالفرشة والمعجون في رمضان؟","title":"حكم استعمال الصائم الفرشة والمعجون","answer":"الجواب: لا حرج في ذلك؛ لكن لا يبلع شيئًا، للرجل والمرأة، يغسل فمه وأسنانه، ويتفل ما يحصل منه، يمجه، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14462/حكم-استعمال-الصاىم-الفرشة-والمعجون","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_744/nour_74412.mp3","categories":["ما لا يفسد الصيام"]},{"id":15899,"question":"يقول: في ليلة من ليالي رمضان قمنا للسحور، ولكنا قمنا متأخرين، والبعض قام متأخرًا كثيرًا، فأكل فطلع الفجر، وهو ما زال يأكل، ولم يكف عن ذلك، فما حكم صومه؟ وما حكم من إذا أذن للكفاف لم يترك الأكل؟ أفيدونا، أفادكم الله.","title":"حكم استمرار الصائم في الأكل أثناء أذان الفجر","answer":"الجواب: من أكل بعد طلوع الفجر عليه أن يعيد، وعليه أن يقضي مع التوبة، أما من أكل وهو يؤذن أو في مكان يشك فيه بطلوع الفجر ما اتضح له الفجر فلا حرج عليه، لكن إذا كان أذن المؤذن يترك، الأذان يوجب الانكفاف عن تناول الطعام والشراب.  لكن لو أكل شيئًا من الطعام أو شرب شيئًا من الماء وهو يؤذن، ولا يعلم بطلوع الفجر فإنه لا حرج؛ لأن المؤذنين يؤذنون على التقويم وعلى ظن الصبح، وليس على يقين الصبح، فإذا شرب شيئًا عند الأذان أو أكل شيئًا عند الأذان فإنه لا يضر -إن شاء الله- إلا إذا كان في مكان يعلم طلوع الفجر، فإنه يمسك، أو في مكان يعلم أن المؤذن إنما يؤذن بعد طلوع الفجر، فإنه يمسك إذا سمع الأذان، أما الأذان المعروف الآن الذي على التقويم هذا لا حرج فيه أن يتناول ما في يده من طعام أو شراب وقت الأذان، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14489/حكم-استمرار-الصاىم-في-الاكل-اثناء-اذان-الفجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_745/nour_74516.mp3","categories":["مفسدات الصيام","ما لا يفسد الصيام"]},{"id":16007,"question":"من حريملاء المستمع حمد بن إبراهيم الصالح يقول: أرجو إفادتي عن وضع الدهان على الجسم في نهار رمضان، مع العلم أن بعض هذه الأدهنة يمتصها الجلد؟جزاكم الله خيرًا.","title":"حكم استعمال الدهان في نهار رمضان","answer":"الجواب: لا حرج في ذلك في حق الصائم، كونه يدهن لا حرج عليه، لا في جسمه كله، أو في بعضه، الأمر واسع، الحمد لله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14625/حكم-استعمال-الدهان-في-نهار-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_747/nour_74711.mp3","categories":["ما لا يفسد الصيام"]},{"id":16025,"question":"على ذكر الحجامة سماحة الشيخ، من أخذ منه دم للتحليل، أو تبرع بالدم لمريض، هل يؤثر هذا على صيامه؟","title":"حكم أخذ الدم من الصائم","answer":"الشيخ: دم التحليل خفيف لا يؤثر، دم التحليل لا يؤثر، لكن إذا أخذ دمًا كثيرًا يتبرع به لمريض، فالأحوط له القضاء إن كان فرضًا، الأحوط له القضاء؛ لأنه يشبه الحجامة من بعض الوجوه.  والصواب عند أهل العلم: أن هذا خاص بالحجامة، لكن إلحاق الدم الكثير بالحجامة قول قوي، وإلا فالمعروف عند أهل العلم الذين فطروا بالحجامة يخصون الحجامة فقط؛ لأنه جاء بها النص، ولا يجعلون الفصد وغيره مفطرًا، ولكن قول من قال: يلحق بها ما يشبهها، قول قوي، أما الشيء القليل، التحليل في إصبعه، أو التحليل من فخذ، أو غيره هذا لا يفطر الصوم على الصحيح، لا يفسد الصوم، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14658/حكم-اخذ-الدم-من-الصاىم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_801/nour_80105.mp3","categories":["ما لا يفسد الصيام"]},{"id":16268,"question":"يقول السائل في هذا  إذا سمع الإنسان الأذان في رمضان من الراديو، ثم أفطر بناءً على أن هذا الأذان لبلده، وتبين أنه لبلد آخر يؤذن قبل بلده، هل يقضي هذا اليوم يا سماحة الشيخ؟","title":"حكم من أفطر على أذان في المذياع يظنه أذان بلده","answer":"الجواب: إذا علم أنه أفطر قبل غروب الشمس؛ يقضي، عليه قضاء، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/14955/حكم-من-افطر-على-اذان-في-المذياع-يظنه-اذان-بلده","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_581/58106.mp3","categories":["مفسدات الصيام","ما لا يفسد الصيام"]},{"id":16333,"question":"هل يجوز للصائم غسل فمه بالفرشاة، والمعجون؟","title":"حكم استعمال معجون الأسنان للصائم","answer":"الجواب: نعم له غسله بالفرشاة والمعجون، لكن يحذر أن يذهب إلى جوفه شيء، يجتهد في بصق ما في فمه من ذلك، حتى لا يبتلع شيئًا، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15020/حكم-استعمال-معجون-الاسنان-للصاىم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_753/nour_753017.mp3","categories":["ما لا يفسد الصيام"]},{"id":16604,"question":"يقول في سؤال آخر: رجل يشك في بعض أيام رمضان، أي في صيامه لبعض أيام رمضان، وما ذاك إلا لما يخرج من فمه من اللعاب الكثير الذي يضطر غالبًا إلى بلعه، خاصة أثناء الصلاة، أو في قاعة الصف الدراسي، أو إذا كان في المسجد، كذلك بعض الأيام يشرب الماء بعد السحور، والمؤذن يؤذن للصلاة، أي أثناء الأذان، وأحيانًا بعيد الانتهاء بقليل، وأحيانًا يخرج من لثته دم مستمر؛ لضعف لثته، فماذا عليه؟ وماذا يفعل وهو الآن قد انتهى من الصيام؟ جزاكم الله خيرًا.","title":"حكم بلع الريق للصائم والشرب أثناء أذان الصبح وبعده","answer":"الجواب: صومه صحيح، وهذا اللعاب لا يضر، كونه يبتلع اللعاب -الريق- لا يضر، أو يبصقه لا يضر، لا يضر الصوم، إنما يضره النخامة -النخامة التي يتجمع النخام من الصدر، أو من الرأس- هذا هو الذي يجب عليه أن يبصقه في ثوبه، أو في أي مكان، ولا يبتلعه في الصوم، وعند جمع من أهل العلم أنه يفطره هذا النخام، أما جنس الريق، جنس اللعاب الذي ليس بنخام فلا يفطر. وهكذا ما يقع من دم اللثة... يقع من الأسنان إذا تعرض للإنسان هذا الدم الخفيف؛ لا يضر الصوم، ولا يضر الوضوء، الوضوء صحيح، والصوم صحيح، ولا يضره ذلك. وهكذا ما يتعلق بالأذان كونك تأكل، أو تشرب، وهو يؤذن الصوم صحيح حتى تعلم طلوع الفجر، فإذا كنت لا تعلم طلوع الفجر، فالأذان يؤذن على الظن، على ظن الوقت، حسب التقويم. لكن الأحوط لك أن تجتهد في أن تفرغ قبل الأذان، تحتاط لصومك، وهكذا يشرب بعيد الأذان -عند فراغ الأذان- من غير تطويل، دقيقة، دقيقتين ما يضر -إن شاء الله- لأنه بالظن فقط، والأصل بقاء الليل، وعدم دخول النهار، هذا هو الأصل، لكن المؤمن يحتاط، يجتهد في الاحتياط حتى يفرغ قبل الأذان، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/15329/حكم-بلع-الريق-للصاىم-والشرب-اثناء-اذان-الصبح-وبعده","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_716/nour_71605.mp3","categories":["ما لا يفسد الصيام"]},{"id":16783,"question":"من المستمع عبدالمنعم محمد الجندي من الأردن -الجامعة الأردنية- كلية الهندسة، رسالة ضمنها سؤالين، في سؤاله الأول يقول: من المعروف أن الصائم إن أكل ناسيًا؛ فليس عليه شيء، هل هذا ينطبق فقط على الصوم المفروض؟ أم على الصوم بشكل عام؟ جزاكم الله خيرًا.","title":"حكم صوم من أكل ناسيًا","answer":"الجواب: على الصوم بشكل عام، الفرض والنفل، رمضان، وغيره، إذا أكل ناسيًا، وشرب ناسيًا؛ فصومه صحيح، والحمد لله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15525/حكم-صوم-من-اكل-ناسيا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_762/nour_76211.mp3","categories":["ما لا يفسد الصيام"]},{"id":16787,"question":"هذا السائل يا سماحة الشيخ من اليمن تعز، يقول: ما هي مفسدات الصوم بغير إرادة الإنسان؟","title":"حكم الصائم إذا تناول مفطرًا بغير إرادته","answer":"الجواب: المفطرات إذا حصل له ما يفطر الصائم باختياره، كأن يشرب، أو يأكل، أو يجامع، أو ما أشبه ذلك؛ أفطر، أما إن كان بغير اختياره مثل أكره على إدخال الماء في فيه بالقوة، والظلم هذا ما يفطر، أو نسي، شرب ناسيًا لا يفطر، أما إذا اختار، شرب وهو يعلم أنه صائم؛ أفطر، أكل وهو يعلم أنه صائم متعمدًا؛ أفطر، جامع كذلك أفطر، أما إذا كان لا.. مكره، الله يقول: مَنْ كَفَرَ بِاللَّهِ مِنْ بَعْدِ إِيمَانِهِ إِلَّا مَنْ أُكْرِهَ وَقَلْبُهُ مُطْمَئِنٌّ بِالإِيمَانِ [النحل:106].  إذا كان إسلامه لا يبطل، إذا كفر بعد الإيمان مكرهًا، وقلبه مطمئن؛ لا يكفر، فمن باب أولى لا يفطر، فلو أن إنسانًا جبره ناس على شرب الماء، أو صبوا في فمه الماء، أو أدخلوا في فمه ما يفطره بالقوة؛ لا يضره ما دام لم يقصد ذلك، وإنما أجبروه عليه؛ فإنه لا يفطر بذلك؛ لأنه مكره. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/15531/حكم-الصاىم-اذا-تناول-مفطرا-بغير-ارادته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_585/58508.mp3","categories":["مفسدات الصيام","ما لا يفسد الصيام"]},{"id":17411,"question":"السائلة تقول في ثاني أسئلتها: هل يجوز للمرأة أن تتناول حبوب منع الدورة حرصًا على صيام شهر رمضان المبارك كاملًا؟","title":"حكم تناول حبوب منع الدورة لأجل الصوم","answer":"الجواب: لا حرج في ذلك أن تتعاطى ما يمنع الدورة من أجل الحج، أو ..... رمضان، لا حرج في ذلك، نعم.  المقدم: جزاكم الله عنا وعن المسلمين خير الجزاء.","link":"https://binbaz.org.sa/fatwas/16276/حكم-تناول-حبوب-منع-الدورة-لاجل-الصوم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_771/nour_77112.mp3","categories":["قضايا المرأة","ما لا يفسد الصيام"]},{"id":17473,"question":"السائلة من جمهورية مصر العربية تقول: أعلم بأنه من نسي فأكل، أو شرب في رمضان فإن صومه صحيح، فهل الحال كذلك إذا كان هذا الصيام، في النفل؟","title":"حكم الأكل ناسيًا في صوم الفرض والنفل","answer":"الجواب: نعم. في الفرض والنفل، يقول النبي ﷺ: من نسي وهو صائم، فأكل، أو شرب؛ فليتم صومه فإنما أطعمه الله وسقاه هذا يعم الفرض، والنفل، وهذا من رحمة الله، كما قال -جل وعلا-: رَبَّنَا لا تُؤَاخِذْنَا إِنْ نَسِينَا أَوْ أَخْطَأْنَا [البقرة:286] وصح عن رسول الله ﷺ أنه قال: يقول الله: قد فعلت والحمد لله، نعم.  المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16369/حكم-الاكل-ناسيا-في-صوم-الفرض-والنفل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_773/nour_77305.mp3","categories":["ما لا يفسد الصيام"]},{"id":17575,"question":"أخيرًا يسأل عن الكحل: هل يؤثر على الصيام أو لا؟","title":"حكم الكحل للصائم","answer":"الجواب: الصواب أنه لا يؤثر، لكن الأفضل في الليل، وإلا فلا يؤثر؛ لأن العين ما هي بمنفذ، لكن بعض العلماء يقول: إذا وجده في الحلق، إذا وجد أثرًا للكحل أو القطور في الحلق قضى، والصحيح أنه لا يلزمه القضاء، لكن كونه يستعمله في الليل هذا هو الأحوط والأفضل، لقوله ﷺ: دع ما يريبك إلى ما لا يريبك. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16502/حكم-الكحل-للصاىم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_839/nour_83903.mp3","categories":["ما لا يفسد الصيام"]},{"id":17641,"question":"بعد هذا رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين، في أحد أسئلته في هذه الرسالة يقول: في ليلةٍ من ليالي رمضان صحونا ومؤذن الفجر يؤذن، فتسحرنا، وصمنا، فهل صيامنا صحيح؟ أم نقضي ذلك اليوم؟ جزاكم الله خيرًا.","title":"حكم من تسحر والمؤذن يؤذن للفجر","answer":"الجواب: إذا كنتم لا تعلمون طلوع الفجر، وتشكون في طلوع الفجر، فالصيام صحيح، أما إذا كنتم تعلمون أن الفجر قد طلع، فعليكم القضاء، والمؤذن يؤذن على تقويم، على ظن الفجر، وليس على يقين الفجر، بل على الظن، أو على التقويم الذي عنده، فمن عرف طلوع الفجر؛ حرم عليه الأكل، وإلا فله الأكل عند الشك، والأحوط له أن يتقدم للأكل قبل الأذان، حتى يستبرئ لصيامه، ويبتعد عن الشبهة، وإذا كان أكله بعد الأذان بوقت طويل، فالأحوط له القضاء، أما إذا كان شيئًا يسيرًا، دقيقة، دقيقتين، أو مع الأذان، فلا حرج إن شاء الله، إذا لم يعلم طلوع الفجر. نعم.\nالمقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/16563/حكم-من-تسحر-والموذن-يوذن-للفجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_726/nour_72608.mp3","categories":["مفسدات الصيام","ما لا يفسد الصيام"]},{"id":17683,"question":"يقول السائل: ما حكم طلوع الدم للصائم في نهار رمضان بدون قصد؟ وهل الاحتلام للصائم وهو نائم في نهار رمضان بدون قصد يبطل الصوم؟","title":"حكم الاحتلام وخروج الدم من الصائم","answer":"الجواب: إذا خرج منه دم بسبب سقطة أو وقع أصابه شيء أو ... أصابه أو حجر أصابه أو رعاف ما يبطل صومه، وهكذا لو احتلم ليس عليه شيء لا بأس عليه؛ لأنه ليس باختياره، لا يضره ما يقع من الدم بغير اختياره كالرعاف أو جرح أصابه سقط على الأرض أو أصابه حجر أو أصابه شيء أخرج منه دمًا ما يضره، لكن لا يحتجم لا يتعمد إخراج الدم، أما الشيء اليسير يعفى عنه. نعم.\nالمقدم: جزاكم الله خير يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16622/حكم-الاحتلام-وخروج-الدم-من-الصاىم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_595/59512.mp3","categories":["ما لا يفسد الصيام"]},{"id":17930,"question":"هل ابتلاع الريق جائز والمرء صائم؟","title":"حكم ابتلاع الصائم للريق","answer":"الجواب: الريق العادي لا بأس به يبتلعه، أما إذا كان فيه بلغم متعقد نخام فلا يبتلعه يلقيه يلفظه.. يلفظه، أما الريق العادي الماء العادي في الريق هذا لا حرج فيه، والحمد لله.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16965/حكم-ابتلاع-الصاىم-للريق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_847/nour_84710.mp3","categories":["ما لا يفسد الصيام"]},{"id":18077,"question":"سمعت من أحد المشايخ أنه بالنسبة لصيام التطوع إذا نسي الصائم فأكل أو شرب فيجب عليه أن يفطر ولا يكمل صيامه، وذلك على عكس صيام رمضان، أفيدونا عن هذا جزاكم الله خيرًا.","title":"حكم الأكل والشرب نسيانًا في صيام التطوع","answer":"الجواب: هذا خطأ، الصواب أنه إذا أكل ناسيًا، أو شرب ناسيًا فصومه صحيح ولا فطر عليه بل صومه صحيح، وهكذا على الصحيح لو جامع ناسيًا أهله فإن صومه صحيح؛ لقول النبي ﷺ في الحديث الصحيح لما سئل عن ذلك قال: من نسي وهو صائم فأكل أو شرب فليتم صومه فإنما أطعمه الله وسقاه خرجه الشيخان في الصحيحين. وقال الله سبحانه: رَبَّنَا لا تُؤَاخِذْنَا إِنْ نَسِينَا أَوْ أَخْطَأْنَا [البقرة:286]، ذكر عن عباده المؤمنين أنهم يدعونه ويقولون: رَبَّنَا لا تُؤَاخِذْنَا إِنْ نَسِينَا أَوْ أَخْطَأْنَا [البقرة:286] فقال الله: قد فعلت هكذا ثبت عن رسول الله ﷺ أن الله جل وعلا قال: نعم، يعني: عفا عنهم إذا فعلوا شيئًا نسيانًا أو خطأً. ومن ذلك إذا أكل ناسيًا في الصوم في رمضان أو في غيره في التطوع أو في القضاء أو في النذور إذا أكل ناسيًا أو شرب ناسيًا أو جامع ناسيًا فلا شيء عليه؛ لقوله عليه الصلاة والسلام: من نسي وهو صائم فأكل أو شرب فليتم صومه، فإنما أطعمه الله وسقاه متفق على صحته. وفي رواية ذكرها الحاكم وغيره وسندها صحيح: من أفطر في رمضان ناسيًا فلا قضاء عليه ولا كفارة وهذا يعم الفطر بالأكل والشرب أو بالجماع أو بغير ذلك إذا كان عن نسيان فإن الله جل وعلا يعفو عنه  فضلًا منه وإحسانًا جل وعلا؛ لأن الإنسان عرضة للنسيان في كل شيء. نعم. المقدم: جزاكم الله خيرًا، إذًا ليس هذا خاص بالنفل؟ الشيخ: لا، عام للفرض والنفل ورمضان وغيره. المقدم: نعم. جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17111/حكم-الاكل-والشرب-نسيانا-في-صيام-التطوع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_903/nour_90303.mp3","categories":["ما لا يفسد الصيام"]},{"id":18122,"question":"السائل أبو حامد يقول: هل الدخان الذي ينبعث من النار يفطر الصائم؟","title":"هل استنشاق الدخان يؤثر على الصيام؟","answer":"الجواب: لا، لا يفطر الصائم الدخان، لكن لا يتعمد إدخاله إلى جوفه سواء طيب وإلا غيره؛ لأن بعض أهل العلم يقول: إذا تعمد إدخاله أفطر به، فينبغي له أن لا يتعمد ذلك، أما الشيء الذي عرض يدخل بغير قصد دخانة عود أو دخان حطب أو ماء فلا يضره، لكن كونه يتعمد يستنشق الطيب أو ما أشبه ذلك من الدخان فهذا بعض أهل العلم يراه يفطر، فينبغي له التحرز من هذا.","link":"https://binbaz.org.sa/fatwas/17165/هل-استنشاق-الدخان-يوثر-على-الصيام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_781/nour_78110.mp3","categories":["ما لا يفسد الصيام"]},{"id":18124,"question":"السائل أبو حامد يقول: هل الدخان الذي ينبعث من النار يفطر الصائم؟","title":"هل استنشاق الدخان يؤثر على الصيام؟","answer":"الجواب: لا، لا يفطر الصائم الدخان، لكن لا يتعمد إدخاله إلى جوفه سواء طيب وإلا غيره؛ لأن بعض أهل العلم يقول: إذا تعمد إدخاله أفطر به، فينبغي له أن لا يتعمد ذلك، أما الشيء الذي عرض يدخل بغير قصد دخانة عود أو دخان حطب أو ماء فلا يضره، لكن كونه يتعمد يستنشق الطيب أو ما أشبه ذلك من الدخان فهذا بعض أهل العلم يراه يفطر، فينبغي له التحرز من هذا.","link":"https://binbaz.org.sa/fatwas/17165/هل-استنشاق-الدخان-يوثر-على-الصيام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_781/nour_78110.mp3","categories":["ما لا يفسد الصيام"]},{"id":18202,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من إحدى الأخوات المستمعات تقول المرسلة: أختكم (هيلة . أ. ع) أختنا عرضنا بعض أسئلتها في حلقة مضت، وفي هذه الحلقة بقي لها عدد من الأسئلة فتسأل هذا السؤال وتقول: ما حكم الشرع في نظركم في استعمال الكحل للصائم؛ حيث أنني بحثت عن الأدلة في ذلك، فوجدت أدلة التحريم ضعيفة، وهل هناك فرق في استخدامه قبل الصوم أو في أثنائه؟ ولكم جزيل الشكر.","title":"حكم استعمال الكحل للصائم","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد: فاستعمال الكحل للصائم لا حرج فيه في أصح قولي العلماء؛ لأن العين ليست منفذًا معتادًا، فلا يضر استعماله، وإذا تركه الإنسان في الليل من باب الاحتياط، والخروج من خلاف العلماء فهو حسن إن شاء الله، وإلا فلا يضر، سواء استعمله في النهار عند الصوم أو في أثناء النهار، كل ذلك لا حرج فيه، إلا أنه في الليل أفضل. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17238/حكم-استعمال-الكحل-للصاىم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_908/nour_90801.mp3","categories":["ما لا يفسد الصيام"]},{"id":19030,"question":"من إحدى الأخوات المستمعات رسالة تقول: المرسلة (س.ع) مصرية ومقيمة في المملكة، تسأل جمعًا من الأسئلة، من بين أسئلتها سؤال يقول: هل معجون الأسنان يفطر الصائم أو لا؟","title":"حكم استعمال الصائم لمعجون الأسنان","answer":"الجواب: معجون الأسنان لا يفطر الصائم، وهكذا السواك، وهكذا تنظيف الفم بالصابون أو غيره، كل هذا لا يفطر الصائم، لكن يحذر الإنسان من دخول شيء إلى جوفه من معجون أو غير المعجون، لا يدخل شيء إلى جوفه، أما كونه ينظف الأسنان بمعجون أو بصابون أو بنوع آخر، ثم يبصق ذلك، لا، لا يضر صومه. أما إن تعمد ابتلاع شيء من ذلك فإنه يفطر الصوم، أما لو ذهب إلى حلقه شيء من غير قصد، أو غلبه ذلك، أو نسيانًا؛ فلا يفطر صومه. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18232/حكم-استعمال-الصاىم-لمعجون-الاسنان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_796/nour_79609.mp3","categories":["ما لا يفسد الصيام"]},{"id":19056,"question":"هل يجب الصوم قضاء الصوم إذا أتت المرأة الدورة الشهرية بعد صلاة المغرب أو قبل الصلاة بعد الإفطار؟","title":"حكم من جاءها الحيض بعد غروب الشمس وهي صائمة","answer":"الجواب: ليس عليها شيء؛ لأنها أكملت الصيام، يعني: إذا جاء الحيض بعد غروب الشمس، ولو قبل الصلاة فلا شيء عليها، أو بعد الصلاة ما في قضاء. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18231/حكم-من-جاءها-الحيض-بعد-غروب-الشمس-وهي-صاىمة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_928/nour_92811.mp3","categories":["الحيض والنفاس","ما لا يفسد الصيام","قضايا المرأة"]},{"id":19114,"question":"رسالة وصلت إلى البرنامج من المستمع: محمد يوسف من جدة، أخونا له جمع من القضايا في إحداها يقول: سماحة الشيخ! ما الحكم فيمن صافح امرأة أجنبية أو تحدث معها في نهار رمضان وهو صائم وأيضًا هي صائمة؟ هل هذا يفسد الصوم أو يجرحه؟ نرجو توجيهنا جزاكم الله خيرًا، وهل من كفارة؟","title":"حكم مصافحة ومحادثة الأجنبية في نهار رمضان وغيره","answer":"الجواب: أولاً: المصافحة للمرأة الأجنبية لا تجوز؛ لأن الرسول عليه السلام قال: إني لا أصافح النساء وقالت عائشة رضي الله عنها: «ما مست يد رسول الله ﷺ يد امرأة قط ما كان يبايعهن إلا بالكلام» يعني: النساء الأجنبيات غير المحارم، أما المحرم كأخته وعمته فلا بأس أن يصافحها. وأما المكالمة للأجنبية فلا بأس بها إذا كانت مكالمة مباحة ليس فيها تهمة ولا ريبة، كي يسألها عن أولادها يسألها عن أبيها يسألها عن حاجة من حوائج الجيران أو الأقارب لا بأس بذلك. أما إن كانت المكالمة للتحدث فيما يتعلق بالفساد والزنا ومواعيد الزنا أو عن شهوة أو عن كشف منها له، بأن يرى محاسنها يرى وجهها يرى محاسنها كل هذا لا يجوز. أما إذا كانت المحادثة مع التستر ومع الحجاب ومع البعد عن الريبة، وليس عن شهوة فإنه لا حرج عليه في ذلك، وقد تحدث النبي ﷺ إلى النساء وتحدث النساء إليه ولا حرج في ذلك والصوم صحيح، لا يضره المصافحة ولا تضره المحادثة إلا إذا كانت عن شهوة وخرج المني، فإنه يبطل الصوم بخروج المني عن شهوة، وعليه أن يعيد الصوم على من خرج منه ذلك أن يعيد الصوم. أما مجرد التحدث ولم يخرج شيء فإنه لا يضر الصوم، وهكذا لو خرج مذي المذي لا يبطل الصوم على الصحيح، وإنما يبطله خروج المني عن شهوة في نهار الصوم. والواجب على المؤمن أن يحذر ما حرم الله عليه، وأن لا يصافح امرأة لا تحل له، وأن لا يتحدث إليها عن شهوة أو ينظر إلى محاسنها، والله يقول جل وعلا: قُلْ لِلْمُؤْمِنِينَ يَغُضُّوا مِنْ أَبْصَارِهِمْ وَيَحْفَظُوا فُرُوجَهُمْ ذَلِكَ أَزْكَى لَهُمْ إِنَّ اللَّهَ خَبِيرٌ بِمَا يَصْنَعُونَ [النور:30] فالتحفظ من أسباب الشر واجب على المؤمن أينما كان، نسأل الله لنا وللمسلمين جميعًا السلامة. نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18284/حكم-مصافحة-ومحادثة-الاجنبية-في-نهار-رمضان-وغيره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_931/nour_93104.mp3","categories":["قضايا المرأة","ما لا يفسد الصيام","النظر والخلوة والاختلاط"]},{"id":19315,"question":"أخيرًا تسأل سماحتكم: هل معجون الأسنان يفطر؟","title":"استعمال معجون الأسنان أثناء الصيام","answer":"الجواب: المعجون لا يفطر إذا لم تبلعه، غسلت به أسنانها وتفلته، لفظته؛ فلا يفطر، أما إذا تعمدت ابتلاعه فإنه يفطر. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18504/استعمال-معجون-الاسنان-اثناء-الصيام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_739/nour_73910.mp3","categories":["ما لا يفسد الصيام"]},{"id":19319,"question":"هل الريق إذا نزل من الحلق يفطر الصائم؟","title":"حكم بلع الريق للصائم","answer":"الجواب: الريق لا يفطر الصائم. المقدم: الحمد لله، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18502/حكم-بلع-الريق-للصاىم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_739/nour_73909.mp3","categories":["ما لا يفسد الصيام"]},{"id":19399,"question":"أختنا تقول: إذا كان الإنسان صائمًا، ونزل منه دم فهل عليه أن يفطر أو يتم صيامه؟","title":"حكم خروج الدم من الصائم","answer":"الجواب: لا يضره ذلك الصائم لا يضره خروج الدم، إلا الحجامة إذا احتجم؛ فالصحيح أنه يفطر بالحجامة، وفيها خلاف بين العلماء لكن الصحيح أنه يفطر؛ لقول النبي ﷺ: أفطر الحاجم والمحجوم أما إذا أرعف أو أصابه جرح في رجله أو في يده وهو صائم فإن صومه صحيح لا يضره ذلك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18626/حكم-خروج-الدم-من-الصاىم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_935/nour_93507.mp3","categories":["ما لا يفسد الصيام"]},{"id":19477,"question":"هذا أخونا السائل: أبو عبد الله من الرياض يقول: سماحة الشيخ! حفظكم الله، وسدد خطاكم، ذهبت أنا والوالدة إلى مكة المكرمة لأداء فريضة العمرة، وبعد وصولنا إلى مكة آخر الليل قررنا أن نستريح في السكن بعض الوقت، وقبل صلاة الفجر فأخذنا النوم فلما استيقظنا سألتني الوالدة: هل أذن الفجر؟ فقلت لها: لا، وأنا لا أعلم، فأكلت علاجًا كان معها، فتبين لنا بعد ذلك بأن أذان الفجر قد أذن منذ عشرين دقيقة، فماذا يجب على الوالدة؟ وهل يلزمني شيء؟","title":"حكم من شرب بعد أذان الفجر من رمضان جاهلًا","answer":"الجواب: عليها أن تقضي اليوم من رمضان، وأنت عليك الاستغفار عن إفتائها بغير علم، تقول: ما أذن وأنت ما تدري، عليك التوبة والاستغفار وعليها القضاء هي. المقدم: أحسن الله إليكم، وبارك فيكم.","link":"https://binbaz.org.sa/fatwas/18725/حكم-من-شرب-بعد-اذان-الفجر-من-رمضان-جاهلا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_939/nour_93913.mp3","categories":["مفسدات الصيام","ما لا يفسد الصيام"]}]
